using System;
using System.Threading;

public sealed class Inventory
{
    public readonly int OwnerId;                 // 플레이어마다 고유
    public readonly object Gate = new object();  // 이 인벤토리를 보호하는 락
    private int _gold;

    public Inventory(int ownerId, int gold)
    {
        OwnerId = ownerId;
        _gold = gold;
    }

    public int Gold
    {
        get { return _gold; }
    }

    // Gate 를 잡은 스레드만 호출한다.
    public void ApplyDelta(int delta)
    {
        _gold += delta;
    }
}

public static class TradeService
{
    // from 의 골드 amount 를 to 로 옮기고 true 를 반환한다.
    // amount <= 0, from 과 to 가 같은 인벤토리, 잔액 부족이면 아무것도 바꾸지 않고 false.
    public static bool Transfer(Inventory from, Inventory to, int amount)
    {
        if (ReferenceEquals(from, to)) return false;
        if (from.Gold < amount) return false;

        lock (from.Gate)
        {
            lock (to.Gate)
            {
                from.ApplyDelta(-amount);
                to.ApplyDelta(amount);
            }
        }
        return true;
    }
}

problems.solutionCode:
using System;
using System.Threading;

public sealed class Inventory
{
    public readonly int OwnerId;                 // 플레이어마다 고유. 락 순서의 기준이 된다
    public readonly object Gate = new object();  // 이 인벤토리를 보호하는 락
    private int _gold;

    public Inventory(int ownerId, int gold)
    {
        OwnerId = ownerId;
        _gold = gold;
    }

    // Monitor 는 재진입이 가능하므로 이미 Gate 를 잡은 스레드가 읽어도 막히지 않는다.
    public int Gold
    {
        get { lock (Gate) { return _gold; } }
    }

    // Gate 를 잡은 스레드만 호출한다.
    public void ApplyDelta(int delta)
    {
        _gold += delta;
    }
}

public static class TradeService
{
    // from 의 골드 amount 를 to 로 옮기고 true 를 반환한다.
    // amount <= 0, from 과 to 가 같은 인벤토리, 잔액 부족이면 아무것도 바꾸지 않고 false.
    public static bool Transfer(Inventory from, Inventory to, int amount)
    {
        if (from == null) throw new ArgumentNullException(nameof(from));
        if (to == null) throw new ArgumentNullException(nameof(to));
        if (amount <= 0 || ReferenceEquals(from, to)) return false;

        // 거래 방향과 무관하게 항상 OwnerId 가 작은 쪽을 먼저 잠근다(전역 락 순서).
        Inventory first = from.OwnerId < to.OwnerId ? from : to;
        Inventory second = ReferenceEquals(first, from) ? to : from;

        lock (first.Gate)
        {
            lock (second.Gate)
            {
                // 잔액 확인과 차감이 같은 임계 구역 안에 있어야 한다.
                if (from.Gold < amount) return false;
                from.ApplyDelta(-amount);
                to.ApplyDelta(amount);
                return true;
            }
        }
    }
}

