public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Threading.Thread Spawn(System.Action body)
    {
        var t = new System.Threading.Thread(() => { try { body(); } catch (System.Exception) { } });
        t.IsBackground = true;
        t.Start();
        return t;
    }

    static string Join(System.Collections.Generic.List<int> log) { return "[" + string.Join(",", log) + "]"; }

    public static void Main()
    {
        Run("fifo-order", () =>
        {
            var log = new System.Collections.Generic.List<int>();
            var d = new MainThreadDispatcher(null);
            if (d.PendingCount != 0) return "새 디스패처의 PendingCount 가 0 이 아님";
            if (d.Pump() != 0) return "빈 큐의 Pump 가 0 을 반환하지 않음";
            for (int i = 1; i <= 5; i++) { int v = i; d.Post(() => log.Add(v)); }
            if (log.Count != 0) return "Post 시점에 작업이 바로 실행됨";
            if (d.PendingCount != 5) return "Post 5회 후 PendingCount 기대 5 / 결과 " + d.PendingCount;
            int n = d.Pump();
            if (n != 5 || Join(log) != "[1,2,3,4,5]") return "기대 5개, [1,2,3,4,5] / 결과 " + n + "개, " + Join(log);
            if (d.PendingCount != 0 || d.Pump() != 0 || log.Count != 5) return "Pump 후 큐가 비지 않았거나 작업이 두 번 실행됨";
            return null;
        });

        Run("post-during-pump-runs-next-frame", () =>
        {
            var log = new System.Collections.Generic.List<int>();
            var d = new MainThreadDispatcher(null);
            d.Post(() => { log.Add(1); d.Post(() => { log.Add(3); d.Post(() => log.Add(4)); }); });
            d.Post(() => log.Add(2));
            int n1 = d.Pump();
            if (n1 != 2 || Join(log) != "[1,2]") return "1번째 Pump 기대 2개, [1,2] / 결과 " + n1 + "개, " + Join(log);
            if (d.PendingCount != 1) return "Pump 도중 Post 된 작업이 대기열에 없음";
            int n2 = d.Pump(); int n3 = d.Pump(); int n4 = d.Pump();
            if (n2 != 1 || n3 != 1 || n4 != 0 || Join(log) != "[1,2,3,4]") return "이후 Pump 기대 1,1,0개, [1,2,3,4] / 결과 " + n2 + "," + n3 + "," + n4 + "개, " + Join(log);
            return null;
        });

        Run("exception-does-not-lose-rest", () =>
        {
            var log = new System.Collections.Generic.List<int>();
            var errors = new System.Collections.Generic.List<string>();
            var d = new MainThreadDispatcher(e => errors.Add(e.Message));
            d.Post(() => log.Add(1));
            d.Post(() => { throw new System.InvalidOperationException("boom-A"); });
            d.Post(() => log.Add(2));
            d.Post(() => { throw new System.ArgumentException("boom-B"); });
            d.Post(() => log.Add(3));
            int n = d.Pump();
            if (n != 5 || Join(log) != "[1,2,3]") return "기대 5개 실행, [1,2,3] / 결과 " + n + "개, " + Join(log);
            if (string.Join("|", errors) != "boom-A|boom-B") return "onError 기대 boom-A|boom-B / 결과 " + string.Join("|", errors);
            d.Post(() => log.Add(4));
            if (d.Pump() != 1 || Join(log) != "[1,2,3,4]") return "예외가 난 프레임 다음의 Pump 가 정상 동작하지 않음";
            var quiet = new MainThreadDispatcher(null);
            quiet.Post(() => { throw new System.Exception("x"); });
            quiet.Post(() => log.Add(5));
            if (quiet.Pump() != 2 || log[log.Count - 1] != 5) return "onError 가 null 일 때 예외 뒤의 작업이 실행되지 않음";
            return null;
        });

        Run("null-action-rejected", () =>
        {
            var d = new MainThreadDispatcher(null);
            try { d.Post(null); return "Post(null) 이 예외를 던지지 않음"; }
            catch (System.ArgumentNullException) { }
            return d.PendingCount == 0 && d.Pump() == 0 ? null : "Post(null) 이 대기열에 들어감";
        });

        Run("pump-only-on-main-thread", () =>
        {
            var log = new System.Collections.Generic.List<int>();
            var d = new MainThreadDispatcher(null);
            d.Post(() => log.Add(1));
            string result = "워커 스레드가 끝나지 않음";
            var t = Spawn(() =>
            {
                try { d.Pump(); result = "다른 스레드의 Pump 가 예외 없이 실행됨"; }
                catch (System.InvalidOperationException) { result = null; }
                catch (System.Exception e) { result = "기대 InvalidOperationException / 결과 " + e.GetType().Name; }
            });
            if (!t.Join(2000)) return "시간 초과(2000ms)";
            if (result != null) return result;
            if (log.Count != 0) return "다른 스레드의 Pump 가 작업을 실행함";
            return d.Pump() == 1 && log.Count == 1 ? null : "거절된 Pump 이후 메인 스레드 Pump 가 작업을 실행하지 못함";
        });

        Run("reentrant-pump-rejected", () =>
        {
            var log = new System.Collections.Generic.List<int>();
            var errors = new System.Collections.Generic.List<string>();
            var d = new MainThreadDispatcher(e => errors.Add(e.GetType().Name));
            d.Post(() => log.Add(1));
            d.Post(() => d.Pump());
            d.Post(() => log.Add(2));
            int n = d.Pump();
            if (n != 3 || Join(log) != "[1,2]") return "기대 3개 실행, [1,2] / 결과 " + n + "개, " + Join(log);
            if (string.Join("|", errors) != "InvalidOperationException") return "작업 안의 Pump 재진입: onError 기대 InvalidOperationException / 결과 " + string.Join("|", errors);
            return null;
        });

        Run("post-not-blocked-by-running-action", () =>
        {
            // 실행 중인 작업이 다른 스레드의 Post 완료를 기다린다. Pump 가 락을 쥔 채 작업을 실행하면 시간 초과가 난다.
            var d = new MainThreadDispatcher(null);
            bool posted = false; int ran = 0;
            d.Post(() =>
            {
                var t = Spawn(() => d.Post(() => ran++));
                posted = t.Join(1500);
            });
            d.Pump();
            if (!posted) return "시간 초과(1500ms): 작업 실행 중에는 다른 스레드의 Post 가 막힘(락을 쥔 채 작업을 실행)";
            if (ran != 0) return "Pump 도중 다른 스레드가 Post 한 작업이 같은 Pump 에서 실행됨";
            return d.Pump() == 1 && ran == 1 ? null : "다른 스레드가 Post 한 작업이 다음 Pump 에서 실행되지 않음";
        });

        Run("concurrent-post-stress", () =>
        {
            const int threads = 4, per = 40000;
            // 경쟁 상태는 한 번의 실행으로는 드러나지 않을 수 있으므로 새 디스패처로 3라운드 반복한다
            for (int round = 0; round < 3; round++)
            {
            // 1단계: 메인 스레드는 기다리기만 하고 워커 4개가 동시에 Post 한다(대기 목록에 대한 동시 쓰기). 끝난 뒤 한 번에 Pump 한다.
            {
                var d0 = new MainThreadDispatcher(null);
                var next0 = new int[threads];
                string bad0 = null; int total0 = 0, go0 = 0;
                var ws = new System.Threading.Thread[threads];
                for (int i = 0; i < threads; i++)
                {
                    int t = i;
                    ws[i] = Spawn(() =>
                    {
                        while (System.Threading.Volatile.Read(ref go0) == 0) System.Threading.Thread.Yield();
                        for (int k = 0; k < per; k++)
                        {
                            int seq = k;
                            d0.Post(() => { if (next0[t] != seq && bad0 == null) bad0 = "워커 " + t + " 의 작업 순서가 뒤바뀜: 기대 " + next0[t] + " / 결과 " + seq; next0[t]++; total0++; });
                        }
                    });
                }
                System.Threading.Thread.Sleep(20);
                System.Threading.Volatile.Write(ref go0, 1);
                var sw0 = System.Diagnostics.Stopwatch.StartNew();
                foreach (var w in ws)
                {
                    int left = 2500 - (int)sw0.ElapsedMilliseconds;
                    if (left < 1 || !w.Join(left)) return "시간 초과(2500ms): 워커 스레드의 Post 가 끝나지 않음";
                }
                int pending0 = d0.PendingCount;
                int n0 = d0.Pump();
                if (bad0 != null) return bad0;
                if (pending0 != threads * per || n0 != threads * per || total0 != threads * per)
                    return "스레드 4개가 동시에 Post 4만 회(그동안 Pump 없음): 기대 " + (threads * per) + "개 / 결과 PendingCount " + pending0 + ", Pump 반환 " + n0 + ", 실행 " + total0 + "개";
            }
            // 2단계: 워커가 Post 하는 동안 메인 스레드가 계속 Pump 한다
            var d = new MainThreadDispatcher(null);
            var next = new int[threads];
            string bad = null; int total = 0, go = 0, done = 0;
            for (int i = 0; i < threads; i++)
            {
                int t = i;
                Spawn(() =>
                {
                    while (System.Threading.Volatile.Read(ref go) == 0) System.Threading.Thread.Yield();
                    try
                    {
                        for (int k = 0; k < per; k++)
                        {
                            int seq = k;
                            d.Post(() => { if (next[t] != seq && bad == null) bad = "워커 " + t + " 의 작업 순서가 뒤바뀜: 기대 " + next[t] + " / 결과 " + seq; next[t]++; total++; });
                        }
                    }
                    finally { System.Threading.Interlocked.Increment(ref done); }
                });
            }
            System.Threading.Thread.Sleep(30);
            System.Threading.Volatile.Write(ref go, 1);
            var sw = System.Diagnostics.Stopwatch.StartNew();
            int sum = 0;
            // 워커가 Post 하는 동안 메인 스레드는 계속 Pump 한다(프레임 루프 흉내)
            while (sw.ElapsedMilliseconds < 3000)
            {
                bool finished = System.Threading.Volatile.Read(ref done) == threads;
                int n = d.Pump();
                sum += n;
                if (finished && n == 0) break;
            }
            if (bad != null) return bad;
            if (total != threads * per || sum != total) return "스레드 4개 x Post 4만 회: 기대 " + (threads * per) + "개 실행 / 결과 실행 " + total + "개, Pump 반환 합 " + sum;
            }
            return null;
        });
    }
}

