using System;

// 상태 이상 8종을 1바이트에 담는다. 멤버 하나가 비트 하나다.
[Flags]
public enum StatusEffect : byte
{
    None       = 0,
    Poison     = 1 << 0,   // 0b_0000_0001 = 0x01
    Burn       = 1 << 1,   // 0b_0000_0010 = 0x02
    Freeze     = 1 << 2,   // 0b_0000_0100 = 0x04
    Stun       = 1 << 3,   // 0b_0000_1000 = 0x08
    Silence    = 1 << 4,   // 0b_0001_0000 = 0x10
    Shield     = 1 << 5,   // 0b_0010_0000 = 0x20
    Haste      = 1 << 6,   // 0b_0100_0000 = 0x40
    Invincible = 1 << 7,   // 0b_1000_0000 = 0x80
    CrowdControl = Freeze | Stun | Silence   // 0b_0001_1100 = 0x1C
}

public static class StatusFlags
{
    // effects 에 든 비트를 모두 켠다(이미 켜져 있으면 그대로).
    public static StatusEffect Add(StatusEffect current, StatusEffect effects)
    {
        return current | effects;
    }

    // effects 에 든 비트를 모두 끈다(이미 꺼져 있으면 그대로).
    public static StatusEffect Remove(StatusEffect current, StatusEffect effects)
    {
        return current & ~effects;
    }

    // effects 에 든 비트가 "전부" 켜져 있으면 true. effects 가 None 이면 true.
    public static bool HasAll(StatusEffect current, StatusEffect effects)
    {
        return (current & effects) == effects;
    }

    // effects 에 든 비트 중 "하나라도" 켜져 있으면 true. effects 가 None 이면 false.
    public static bool HasAny(StatusEffect current, StatusEffect effects)
    {
        return (current & effects) != 0;
    }

    // 켜져 있는 상태 이상의 개수(0 ~ 8).
    public static int CountActive(StatusEffect current)
    {
        int bits = (int)current;
        int count = 0;
        while (bits != 0)
        {
            bits &= bits - 1;   // 가장 낮은 1 비트 하나를 지운다
            count++;
        }
        return count;
    }
}

