using System;
using System.Collections.Generic;

public static class CombatMath
{
    // 최종 피해 = attack x percent / 100 (소수점 이하 버림).
    // attack: 0 ~ 2,000,000,000, percent: 0 ~ 1000.
    // 결과가 int.MaxValue 를 넘으면 int.MaxValue 를 반환한다.
    public static int ScaleDamage(int attack, int percent)
    {
        // 곱셈을 long 으로 한다: 최댓값 2,000,000,000 x 1000 = 2 x 10^12 은 long 범위 안이다.
        // 나눗셈은 곱셈 뒤에 한다(먼저 나누면 소수부가 버려진다).
        long scaled = (long)attack * percent / 100;
        return scaled > int.MaxValue ? int.MaxValue : (int)scaled;
    }

    // 스킬을 다시 쓸 수 있을 때까지 남은 시간(ms). 이미 쓸 수 있으면 0.
    // 두 값은 서버 시작 후 경과한 밀리초다(값이 한 바퀴 도는 경우는 다루지 않는다).
    public static uint RemainingCooldownMs(uint readyAtMs, uint nowMs)
    {
        // 부호 없는 뺄셈은 음수가 될 수 없다. 빼기 전에 비교한다.
        return nowMs >= readyAtMs ? 0u : readyAtMs - nowMs;
    }

    // 체력 게이지에 표시할 퍼센트(0 ~ 100, 소수점 이하 버림).
    // 0 <= hp <= maxHp, 1 <= maxHp <= 2,000,000,000.
    public static int HpPercent(int hp, int maxHp)
    {
        // 곱하고 나서 나눈다. hp x 100 은 최대 2 x 10^11 이라 int 를 넘으므로 long 으로 곱한다.
        return (int)((long)hp * 100 / maxHp);
    }
}

// 다단 히트 스킬: 한 번의 시전에서 같은 대상은 한 번만 맞는다.
public sealed class HitRegistry
{
    // id 는 정수 그대로 보관한다. float 는 2^24(16,777,216)보다 큰 정수 중 일부만 표현한다(16,777,217 은 16,777,216 이 된다).
    private readonly HashSet<int> _hitIds = new HashSet<int>();

    public int Count => _hitIds.Count;

    // 이번 시전에서 처음 맞는 대상이면 기록하고 true, 이미 맞은 대상이면 false.
    public bool TryRegisterHit(int targetId)
    {
        return _hitIds.Add(targetId);
    }

    public void Clear()
    {
        _hitIds.Clear();
    }
}

