problems.solutionCode:
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Threading;

// 용량이 고정된 스레드 안전 FIFO 큐. 가득 차면 넣는 쪽이, 비면 꺼내는 쪽이 기다린다.
public sealed class BoundedBlockingQueue<T>
{
    private readonly object _gate = new object();
    // 아래 필드는 모두 _gate 로 보호한다.
    private readonly T[] _buffer;   // 원형 버퍼
    private int _head;              // 다음에 꺼낼 위치
    private int _count;
    private int _waiters;           // Monitor.Wait 중인 스레드 수
    private bool _completed;

    // capacity 가 1 보다 작으면 ArgumentOutOfRangeException.
    public BoundedBlockingQueue(int capacity)
    {
        if (capacity < 1) throw new ArgumentOutOfRangeException(nameof(capacity));
        _buffer = new T[capacity];
    }

    public int Capacity => _buffer.Length;

    public int Count
    {
        get { lock (_gate) { return _count; } }
    }

    // 자리가 있으면 바로 넣고 true. 가득 차 있으면 최대 timeoutMs 동안 자리를 기다린다.
    // 시간 안에 자리가 나지 않았거나 Complete 된 큐면 false(이때 item 은 들어가지 않는다).
    // timeoutMs: 0 = 기다리지 않음, Timeout.Infinite(-1) = 무한 대기, -1 보다 작으면 ArgumentOutOfRangeException.
    public bool TryEnqueue(T item, int timeoutMs)
    {
        if (timeoutMs < Timeout.Infinite) throw new ArgumentOutOfRangeException(nameof(timeoutMs));
        lock (_gate)
        {
            if (!WaitLocked(true, timeoutMs)) return false;
            _buffer[(_head + _count) % _buffer.Length] = item;
            _count++;
            WakeWaitersLocked();
            return true;
        }
    }

    // 항목이 있으면 바로 꺼내고 true. 비어 있으면 최대 timeoutMs 동안 항목을 기다린다.
    // 시간 안에 항목이 오지 않았거나, Complete 된 큐가 비어 있으면 false(이때 item 은 default).
    // Complete 뒤에도 남아 있는 항목은 꺼낼 수 있다. timeoutMs 의 의미는 TryEnqueue 와 같다.
    public bool TryDequeue(int timeoutMs, out T item)
    {
        if (timeoutMs < Timeout.Infinite) throw new ArgumentOutOfRangeException(nameof(timeoutMs));
        lock (_gate)
        {
            if (!WaitLocked(false, timeoutMs))
            {
                item = default(T);
                return false;
            }
            item = _buffer[_head];
            _buffer[_head] = default(T);   // 꺼낸 칸이 객체를 붙잡고 있지 않게 한다
            _head = (_head + 1) % _buffer.Length;
            _count--;
            WakeWaitersLocked();
            return true;
        }
    }

    // 더 이상 넣지 않겠다고 선언한다. 여러 번 불러도 된다. 기다리던 스레드를 모두 깨운다.
    public void Complete()
    {
        lock (_gate)
        {
            _completed = true;
            WakeWaitersLocked();
        }
    }

    // _gate 를 쥔 채 호출한다. forSpace 가 true 면 빈자리를, false 면 항목을 기다린다.
    // 진행해도 되면 true, 완료되었거나 시간이 다 되면 false.
    private bool WaitLocked(bool forSpace, int timeoutMs)
    {
        long startedAt = Stopwatch.GetTimestamp();   // 대기 시간은 이 시점부터 한 번만 잰다
        while (true)
        {
            // 깨어날 때마다 조건을 처음부터 다시 확인한다(다른 스레드가 먼저 가져갔을 수 있다).
            if (forSpace)
            {
                if (_completed) return false;
                if (_count < _buffer.Length) return true;
            }
            else
            {
                if (_count > 0) return true;    // 완료 뒤에도 남은 항목은 꺼낸다
                if (_completed) return false;
            }

            if (timeoutMs == 0) return false;

            int waitMs = Timeout.Infinite;
            if (timeoutMs > 0)
            {
                // 이미 기다린 시간을 빼고 남은 시간만큼만 다시 기다린다(올림: 제한 시간보다 일찍 포기하지 않는다)
                double remaining = timeoutMs - Stopwatch.GetElapsedTime(startedAt).TotalMilliseconds;
                if (remaining <= 0) return false;
                waitMs = (int)Math.Ceiling(remaining);
            }

            _waiters++;
            try { Monitor.Wait(_gate, waitMs); }   // 락을 놓고 잠들었다가, 락을 다시 얻은 뒤 돌아온다
            finally { _waiters--; }
        }
    }

    // 넣는 쪽과 꺼내는 쪽이 같은 대기열에서 기다리므로 Pulse 하나로는 엉뚱한 쪽이 깨어날 수 있다.
    private void WakeWaitersLocked()
    {
        if (_waiters > 0) Monitor.PulseAll(_gate);
    }
}

