problems.solutionCode:
using System;

// 닉네임을 서버 패킷의 고정 슬롯(UTF-8 바이트 단위)에 담기 위한 도우미.
public static class NicknameBytes
{
    // s 를 UTF-8 로 인코딩했을 때의 바이트 수.
    // 짝이 없는 서로게이트는 Encoding.UTF8 과 같이 U+FFFD(3바이트)로 바뀐다고 보고 센다.
    // s 가 null 이면 ArgumentNullException.
    public static int Utf8ByteCount(string s)
    {
        if (s == null) throw new ArgumentNullException(nameof(s));
        int bytes = 0;
        for (int i = 0; i < s.Length; )
        {
            bytes += NextCodePoint(s, i, out int chars);
            i += chars;
        }
        return bytes;
    }

    // UTF-8 로 maxBytes 바이트 이하가 되는 s 의 접두사 중 가장 긴 것을 돌려준다.
    // 코드 포인트 경계에서만 자른다: 서로게이트 쌍의 두 char 사이에서는 절대 자르지 않는다.
    // s 가 null 이면 ArgumentNullException, maxBytes 가 음수면 ArgumentOutOfRangeException.
    public static string TruncateToUtf8Bytes(string s, int maxBytes)
    {
        if (s == null) throw new ArgumentNullException(nameof(s));
        if (maxBytes < 0) throw new ArgumentOutOfRangeException(nameof(maxBytes));
        int bytes = 0, i = 0;
        while (i < s.Length)
        {
            int size = NextCodePoint(s, i, out int chars);
            if (bytes + size > maxBytes) break;   // 이 코드 포인트는 통째로 들어가지 않으면 버린다
            bytes += size;
            i += chars;
        }
        return i == s.Length ? s : s.Substring(0, i);
    }

    // s[i] 에서 시작하는 코드 포인트 하나의 UTF-8 바이트 수를 돌려주고, 그 코드 포인트가 차지하는 char 수(1 또는 2)를 chars 로 알려 준다.
    private static int NextCodePoint(string s, int i, out int chars)
    {
        char c = s[i];
        chars = 1;
        if (c <= 0x7F) return 1;            // U+0000..U+007F: ASCII
        if (c <= 0x7FF) return 2;           // U+0080..U+07FF
        if (char.IsHighSurrogate(c) && i + 1 < s.Length && char.IsLowSurrogate(s[i + 1]))
        {
            chars = 2;                      // 서로게이트 쌍 = U+10000..U+10FFFF 하나
            return 4;
        }
        return 3;                           // 나머지 BMP(한글 음절 포함). 짝 없는 서로게이트도 U+FFFD 로 바뀌어 3바이트
    }
}

