problems.solutionCode:
using System;
using System.Collections.Generic;

// 최근에 사용한 에셋을 capacity 개까지만 메모리에 두는 LRU 캐시(단일 스레드용).
// 한계: 상점 목록을 한 번 끝까지 훑듯 한 번만 쓰는 아이콘이 몰려 들어오면, 자주 쓰는 장비 아이콘까지 밀려난다(캐시 오염).
public sealed class LruCache<TKey, TValue>
{
    private readonly int _capacity;
    private readonly Action<TKey, TValue> _onEvict;
    // 키 → 사용 순서 리스트의 노드. 노드를 바로 찾으므로 리스트를 훑지 않는다.
    private readonly Dictionary<TKey, LinkedListNode<KeyValuePair<TKey, TValue>>> _map;
    // First = 가장 최근에 사용, Last = 가장 오래 사용되지 않음(다음에 밀려날 항목).
    private readonly LinkedList<KeyValuePair<TKey, TValue>> _order = new LinkedList<KeyValuePair<TKey, TValue>>();

    // capacity 가 1 보다 작으면 ArgumentOutOfRangeException.
    // onEvict: 용량 때문에 항목이 밀려날 때 (key, value) 로 한 번 호출된다. null 이면 호출하지 않는다.
    public LruCache(int capacity, Action<TKey, TValue> onEvict)
    {
        if (capacity < 1) throw new ArgumentOutOfRangeException(nameof(capacity));
        _capacity = capacity;
        _onEvict = onEvict;
        _map = new Dictionary<TKey, LinkedListNode<KeyValuePair<TKey, TValue>>>(capacity);
    }

    public int Capacity => _capacity;

    public int Count => _map.Count;

    // 있으면 value 를 채우고 true. 그 항목은 "가장 최근에 사용"이 된다.
    // 없으면 false, value 는 default. 사용 순서는 바뀌지 않는다.
    public bool TryGet(TKey key, out TValue value)
    {
        if (_map.TryGetValue(key, out var node))
        {
            MoveToFront(node);
            value = node.Value.Value;
            return true;
        }
        value = default(TValue);
        return false;
    }

    // 없는 키면 추가하고, 있는 키면 값을 바꾼다. 어느 쪽이든 그 항목이 "가장 최근에 사용"이 된다.
    // 새 키를 추가할 때 이미 Capacity 개가 들어 있으면, 먼저 가장 오래 사용되지 않은 항목을 빼고 onEvict 를 호출한다.
    // 있는 키의 값을 바꿀 때는 아무것도 밀려나지 않으며 onEvict 를 호출하지 않는다.
    public void Put(TKey key, TValue value)
    {
        if (_map.TryGetValue(key, out var node))
        {
            node.Value = new KeyValuePair<TKey, TValue>(key, value);
            MoveToFront(node);
            return;
        }

        LinkedListNode<KeyValuePair<TKey, TValue>> slot = null;
        if (_map.Count == _capacity)
        {
            // 가장 오래 사용되지 않은 항목(리스트 끝)을 뺀다. 노드는 새 항목에 다시 쓴다.
            slot = _order.Last;
            _order.RemoveLast();
            KeyValuePair<TKey, TValue> old = slot.Value;
            _map.Remove(old.Key);
            _onEvict?.Invoke(old.Key, old.Value);
        }

        var entry = new KeyValuePair<TKey, TValue>(key, value);
        if (slot == null) slot = new LinkedListNode<KeyValuePair<TKey, TValue>>(entry);
        else slot.Value = entry;
        _order.AddFirst(slot);
        _map.Add(key, slot);
    }

    // 들어 있는지만 확인한다. 사용 순서는 바뀌지 않는다.
    public bool ContainsKey(TKey key)
    {
        return _map.ContainsKey(key);
    }

    // 디버그 UI 용: 가장 최근에 사용한 키부터 가장 오래된 키 순서. 사용 순서는 바뀌지 않는다.
    public TKey[] KeysByRecency()
    {
        var keys = new TKey[_map.Count];
        int i = 0;
        for (var n = _order.First; n != null; n = n.Next) keys[i++] = n.Value.Key;
        return keys;
    }

    // 노드를 리스트 맨 앞(가장 최근)으로 옮긴다. 떼었다 다시 붙일 뿐이라 O(1) 이고 할당이 없다.
    private void MoveToFront(LinkedListNode<KeyValuePair<TKey, TValue>> node)
    {
        if (node == _order.First) return;
        _order.Remove(node);
        _order.AddFirst(node);
    }
}

