public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Keys(LruCache<string, int> c) { return string.Join(",", c.KeysByRecency()); }

    // 밀려난 (키, 값) 을 순서대로 기록하는 캐시
    static LruCache<string, int> Make(int cap, System.Collections.Generic.List<string> evicted)
    {
        return new LruCache<string, int>(cap, (k, v) => evicted.Add(k + "=" + v));
    }

    public static void Main()
    {
        Run("capacity-and-arguments", () =>
        {
            foreach (int bad in new[] { 0, -1 })
            {
                try { new LruCache<string, int>(bad, null); return "capacity " + bad + " 에 ArgumentOutOfRangeException 이 나지 않음"; }
                catch (System.ArgumentOutOfRangeException) { }
            }
            var c = new LruCache<string, int>(3, null);
            if (c.Capacity != 3 || c.Count != 0 || c.KeysByRecency().Length != 0) return "새 캐시(용량 3) 기대 Capacity 3, Count 0, 키 없음";
            int v = 7;
            if (c.TryGet("sword", out v) || v != 0) return "빈 캐시의 TryGet 기대 false, value 0 / 결과 value " + v;
            c.Put("sword", 1); c.Put("shield", 2);
            if (c.Count != 2 || !c.TryGet("sword", out v) || v != 1) return "Put 2개 뒤 Count 2, TryGet(\"sword\") = 1 이어야 함";
            try { c.Put(null, 5); return "null 키 Put 에 ArgumentNullException 이 나지 않음"; }
            catch (System.ArgumentNullException) { }
            c.Put("potion", 3); c.Put("bow", 4);   // onEvict 가 null 이어도 밀어내기가 동작해야 한다
            return c.Count == 3 && !c.ContainsKey("shield") ? null : "onEvict 가 null 인 캐시에서 밀어내기 결과가 틀림(Count " + c.Count + ", 키 " + Keys(c) + ")";
        });

        Run("evicts-least-recently-used", () =>
        {
            var ev = new System.Collections.Generic.List<string>();
            var c = Make(3, ev);
            c.Put("A", 1); c.Put("B", 2); c.Put("C", 3);
            if (ev.Count != 0) return "용량 안에서 onEvict 가 호출됨: " + string.Join(";", ev);
            if (Keys(c) != "C,B,A") return "A,B,C 를 넣은 뒤 최근 순서 기대 C,B,A / 결과 " + Keys(c);
            c.Put("D", 4);
            if (string.Join(";", ev) != "A=1") return "용량 3 에서 D 를 넣을 때 기대 밀려남 A=1 / 결과 " + string.Join(";", ev);
            if (c.Count != 3 || c.ContainsKey("A") || Keys(c) != "D,C,B") return "D 추가 뒤 기대 Count 3, 키 D,C,B / 결과 " + c.Count + ", " + Keys(c);
            c.Put("E", 5); c.Put("F", 6);
            return string.Join(";", ev) == "A=1;B=2;C=3" && Keys(c) == "F,E,D" ? null : "연속 추가 시 기대 밀려남 A=1;B=2;C=3, 키 F,E,D / 결과 " + string.Join(";", ev) + ", " + Keys(c);
        });

        Run("tryget-counts-as-use", () =>
        {
            var ev = new System.Collections.Generic.List<string>();
            var c = Make(3, ev);
            c.Put("A", 1); c.Put("B", 2); c.Put("C", 3);
            int v = -1;
            if (!c.TryGet("A", out v) || v != 1) return "TryGet(\"A\") 기대 true, 1";
            if (Keys(c) != "A,C,B") return "TryGet(\"A\") 뒤 최근 순서 기대 A,C,B / 결과 " + Keys(c);
            if (c.TryGet("Z", out v)) return "없는 키 Z 의 TryGet 이 true";
            if (Keys(c) != "A,C,B") return "없는 키의 TryGet 이 순서를 바꿈: " + Keys(c);
            c.Put("D", 4);
            return string.Join(";", ev) == "B=2" && Keys(c) == "D,A,C" ? null : "A 를 읽은 뒤 D 추가: 기대 밀려남 B=2, 키 D,A,C / 결과 " + string.Join(";", ev) + ", " + Keys(c);
        });

        Run("put-existing-refreshes-no-evict", () =>
        {
            var ev = new System.Collections.Generic.List<string>();
            var c = Make(3, ev);
            c.Put("A", 1); c.Put("B", 2); c.Put("C", 3);
            c.Put("A", 10);
            if (ev.Count != 0) return "가득 찬 캐시에서 있는 키 A 의 값을 바꿨는데 onEvict 호출: " + string.Join(";", ev);
            int v = -1;
            if (c.Count != 3 || !c.TryGet("A", out v) || v != 10) return "Put(\"A\", 10) 뒤 기대 Count 3, A = 10 / 결과 Count " + c.Count + ", A = " + v;
            c.Put("B", 20);
            if (Keys(c) != "B,A,C") return "Put(\"B\", 20) 뒤 최근 순서 기대 B,A,C / 결과 " + Keys(c);
            c.Put("D", 4);
            return string.Join(";", ev) == "C=3" && Keys(c) == "D,B,A" ? null : "기대 밀려남 C=3, 키 D,B,A / 결과 " + string.Join(";", ev) + ", " + Keys(c);
        });

        Run("contains-and-listing-do-not-count", () =>
        {
            var ev = new System.Collections.Generic.List<string>();
            var c = Make(2, ev);
            c.Put("A", 1); c.Put("B", 2);
            if (!c.ContainsKey("A") || c.ContainsKey("Z")) return "ContainsKey 결과가 틀림";
            c.KeysByRecency(); c.KeysByRecency();
            if (c.Count != 2 || Keys(c) != "B,A") return "ContainsKey / KeysByRecency 가 순서를 바꿈: " + Keys(c);
            c.Put("C", 3);
            return string.Join(";", ev) == "A=1" ? null : "ContainsKey(\"A\") 는 사용으로 치지 않으므로 기대 밀려남 A=1 / 결과 " + string.Join(";", ev);
        });

        Run("capacity-one", () =>
        {
            var ev = new System.Collections.Generic.List<string>();
            var c = Make(1, ev);
            c.Put("A", 1); c.Put("A", 2);
            if (ev.Count != 0 || c.Count != 1) return "용량 1 에서 같은 키를 다시 Put 했는데 밀려남 발생: " + string.Join(";", ev);
            c.Put("B", 3);
            int v = -1;
            if (string.Join(";", ev) != "A=2" || c.TryGet("A", out v) || !c.TryGet("B", out v) || v != 3) return "용량 1 에서 B 추가: 기대 밀려남 A=2, B = 3 / 결과 " + string.Join(";", ev);
            return Keys(c) == "B" ? null : "키 목록 기대 B / 결과 " + Keys(c);
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            for (int round = 0; round < 40; round++)
            {
                int cap = 1 + round % 6;
                var ev = new System.Collections.Generic.List<string>();
                var refEv = new System.Collections.Generic.List<string>();
                var c = Make(cap, ev);
                var keys = new System.Collections.Generic.List<string>();   // 참조 구현: 앞쪽이 가장 최근
                var vals = new System.Collections.Generic.Dictionary<string, int>();
                for (int step = 0; step < 400; step++)
                {
                    string k = "k" + rng.Next(cap * 2 + 1);
                    int op = rng.Next(10), v;
                    string what;
                    if (op < 4)
                    {
                        int nv = rng.Next(1000);
                        what = "Put(" + k + ", " + nv + ")";
                        c.Put(k, nv);
                        if (keys.Remove(k)) { } else if (keys.Count == cap) { string last = keys[keys.Count - 1]; keys.RemoveAt(keys.Count - 1); refEv.Add(last + "=" + vals[last]); vals.Remove(last); }
                        keys.Insert(0, k); vals[k] = nv;
                    }
                    else if (op < 8)
                    {
                        what = "TryGet(" + k + ")";
                        bool hit = c.TryGet(k, out v);
                        bool exp = keys.Remove(k);
                        if (exp) keys.Insert(0, k);
                        if (hit != exp || (exp && v != vals[k]) || (!exp && v != 0)) return "용량 " + cap + ", " + step + "번째 연산 " + what + " 의 결과가 참조 구현과 다름";
                    }
                    else
                    {
                        what = "ContainsKey(" + k + ")";
                        if (c.ContainsKey(k) != keys.Contains(k)) return "용량 " + cap + ", " + step + "번째 연산 " + what + " 의 결과가 참조 구현과 다름";
                    }
                    if (string.Join(";", ev) != string.Join(";", refEv)) return "용량 " + cap + ", " + step + "번째 연산 " + what + " 뒤 밀려난 항목이 다름: 기대 [" + string.Join(";", refEv) + "] / 결과 [" + string.Join(";", ev) + "]";
                    if (c.Count != keys.Count || Keys(c) != string.Join(",", keys)) return "용량 " + cap + ", " + step + "번째 연산 " + what + " 뒤 기대 키 " + string.Join(",", keys) + " / 결과 " + Keys(c);
                }
            }
            return null;
        });

        Run("large-capacity-constant-time", () =>
        {
            // 용량 50,000 에 40만 번의 Put / TryGet(키 범위가 용량의 4배라 Put 의 대부분이 밀어내기를 일으킨다).
            // 연산이나 밀어내기마다 전체를 훑는 O(n) 구현은 수십억 번 비교하게 되어 제한 시간을 넘긴다.
            string result = "시간 초과(3000ms): 용량 50,000 에서 40만 번의 연산이 끝나지 않음(연산이나 밀어내기마다 전체를 훑는 O(n) 구현으로 보임)";
            var t = new System.Threading.Thread(() =>
            {
                try
                {
                    const int cap = 50000;
                    long evictions = 0;
                    var c = new LruCache<int, int>(cap, (k, v) => { if (v != k * 3) throw new System.Exception("값 불일치"); evictions++; });
                    var rng = new System.Random(7);
                    int hits = 0;
                    for (int i = 0; i < 400000; i++)
                    {
                        int k = rng.Next(cap * 4), v;
                        if ((i & 1) == 0) c.Put(k, k * 3);
                        else if (c.TryGet(k, out v)) { if (v != k * 3) { result = "TryGet 이 잘못된 값을 돌려줌"; return; } hits++; }
                    }
                    if (c.Count != cap) { result = "기대 Count " + cap + " / 결과 " + c.Count; return; }
                    if (evictions == 0 || hits == 0) { result = "밀려남 " + evictions + "회, 적중 " + hits + "회: 값이 0 이면 안 됨"; return; }
                    result = null;
                }
                catch (System.Exception e) { result = "예외 발생: " + e.GetType().Name; }
            });
            t.IsBackground = true;
            t.Start();
            return t.Join(3000) ? result : "시간 초과(3000ms): 용량 50,000 에서 40만 번의 연산이 끝나지 않음(연산이나 밀어내기마다 전체를 훑는 O(n) 구현으로 보임)";
        });
    }
}

problems.starterCode:
using System;
using System.Collections.Generic;
using System.Threading;

// 아이콘 아틀라스 텍스처(만들 때마다 GPU 메모리를 새로 잡는다고 생각하자).
public sealed class IconAtlas
{
    public IconAtlas(int textureId) { TextureId = textureId; }
    public int TextureId { get; }
}

// 게임 데이터 레지스트리. 여러 로딩 스레드가 처음 접근할 때 데이터를 지연 로드한다.
public sealed class GameDataRegistry
{
    private readonly Func<IEnumerable<string>> _readItemLines;   // "id=이름" 줄을 디스크에서 읽는다(느리다)
    private readonly object _gate = new object();
    private Dictionary<int, string> _itemNames;
    private readonly Lazy<IconAtlas> _atlas;

    public GameDataRegistry(Func<IEnumerable<string>> readItemLines, Func<IconAtlas> buildAtlas)
    {
        _readItemLines = readItemLines;
        // 락 비용을 아끼려고 PublicationOnly 를 골랐다.
        _atlas = new Lazy<IconAtlas>(buildAtlas, LazyThreadSafetyMode.PublicationOnly);
    }

    public bool TryGetItemName(int id, out string name)
    {
        return ItemNames.TryGetValue(id, out name);
    }

    public int ItemCount => ItemNames.Count;

    public IconAtlas Atlas => _atlas.Value;

    // 이중 확인 잠금: 이미 로드되었으면 락 없이 바로 돌려준다.
    private Dictionary<int, string> ItemNames
    {
        get
        {
            if (_itemNames == null)
            {
                lock (_gate)
                {
                    _itemNames = new Dictionary<int, string>();
                    foreach (string line in _readItemLines())
                    {
                        int eq = line.IndexOf('=');
                        _itemNames[int.Parse(line.Substring(0, eq))] = line.Substring(eq + 1);
                    }
                }
            }
            return _itemNames;
        }
    }
}

