    public IconAtlas(int textureId) { TextureId = textureId; }
    public int TextureId { get; }
}

// 게임 데이터 레지스트리. 여러 로딩 스레드가 처음 접근할 때 데이터를 지연 로드한다.
public sealed class GameDataRegistry
{
    private readonly Func<IEnumerable<string>> _readItemLines;   // "id=이름" 줄을 디스크에서 읽는다(느리다)
    private readonly object _gate = new object();
    // 끝까지 채운 테이블만 대입한다. 한 번 대입된 뒤에는 바뀌지 않는다.
    // 락 밖에서도 읽히므로 Volatile.Read / Volatile.Write 로만 접근해 순서 요구를 코드에 드러낸다.
    private Dictionary<int, string> _itemNames;
    private readonly Lazy<IconAtlas> _atlas;

    public GameDataRegistry(Func<IEnumerable<string>> readItemLines, Func<IconAtlas> buildAtlas)
    {
        _readItemLines = readItemLines;
        // ExecutionAndPublication(기본값): 생성 함수는 한 스레드에서 한 번만 실행되고, 나머지 스레드는 기다렸다가 같은 값을 받는다.
        _atlas = new Lazy<IconAtlas>(buildAtlas, LazyThreadSafetyMode.ExecutionAndPublication);
    }

    public bool TryGetItemName(int id, out string name)
    {
        return ItemNames.TryGetValue(id, out name);
    }

    public int ItemCount => ItemNames.Count;

    public IconAtlas Atlas => _atlas.Value;

    // 이중 확인 잠금: 이미 로드되었으면 락 없이 바로 돌려준다.
    private Dictionary<int, string> ItemNames
    {
        get
        {
            Dictionary<int, string> items = Volatile.Read(ref _itemNames);   // 1차 확인(락 없음). 필드는 한 번만 읽는다
            if (items != null) return items;
            lock (_gate)
            {
                items = _itemNames;                        // 2차 확인: 락을 기다리는 동안 다른 스레드가 로드를 끝냈을 수 있다
                if (items == null)
                {
                    items = LoadItems();                   // 지역 변수에 끝까지 채운 다음
                    Volatile.Write(ref _itemNames, items); // 완성된 테이블만 공개한다. 로드가 예외로 끝나면 필드는 null 로 남아 다음 호출이 다시 시도한다
                }
                return items;
            }
        }
    }

    private Dictionary<int, string> LoadItems()
    {
        var items = new Dictionary<int, string>();
        foreach (string line in _readItemLines())
        {
            int eq = line.IndexOf('=');
            items[int.Parse(line.Substring(0, eq))] = line.Substring(eq + 1);
        }
        return items;
    }
}

