public static class __Judge
{
    static readonly System.Diagnostics.Stopwatch Clock = System.Diagnostics.Stopwatch.StartNew();
    const int TotalBudgetMs = 9000, CaseBudgetMs = 3500, StackBytes = 256 * 1024;

    // 채점 환경은 동시에 살아 있는 스레드 수를 제한한다(이 테스트는 케이스 스레드 1 + 워커 2 만 쓴다).
    // 스레드 생성이 일시적으로 실패(OutOfMemoryException)하면 잠깐 뒤 다시 만든다.
    static System.Threading.Thread StartThread(System.Threading.ThreadStart body)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (true)
        {
            var t = new System.Threading.Thread(body, StackBytes) { IsBackground = true };
            try { t.Start(); return t; }
            catch (System.OutOfMemoryException) { if (sw.ElapsedMilliseconds > 300) throw; System.Threading.Thread.Sleep(5); }
        }
    }

    // 케이스마다 별도 스레드에서 실행하고, 제한 시간 안에 끝나지 않으면 [FAIL] 로 보고한다(채점기가 멈추지 않게 한다).
    static void Run(string id, System.Func<string> body)
    {
        string err;
        int budget = (int)System.Math.Min(CaseBudgetMs, TotalBudgetMs - Clock.ElapsedMilliseconds);
        if (budget <= 0) err = "앞선 케이스들이 제한 시간을 다 써서 실행하지 못함";
        else
        {
            string result = null;
            try
            {
                var t = StartThread(() =>
                {
                    try { result = body(); }
                    catch (System.Exception e) { result = "예외 발생: " + e.GetType().Name; }
                });
                err = t.Join(budget) ? result : "시간 초과(" + budget + "ms): 호출이 돌아오지 않음(교착 의심)";
            }
            catch (System.Exception e) { err = "케이스 스레드를 만들 수 없음(" + e.GetType().Name + ")"; }
        }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 아이템 줄 공급자. 호출 횟수를 세고, 첫 호출에서 지정한 줄을 내놓기 직전에 멈추거나 예외를 던질 수 있다(주입한 훅).
    sealed class Source
    {
        public int Calls;
        public int PauseBeforeLine = -1, ThrowBeforeLine = -1;
        public readonly System.Threading.ManualResetEventSlim Paused = new System.Threading.ManualResetEventSlim(false);
        public readonly System.Threading.ManualResetEventSlim Release = new System.Threading.ManualResetEventSlim(false);
        static readonly string[] Lines = { "1=Sword", "2=Shield", "3=Potion" };
        public System.Collections.Generic.IEnumerable<string> Read() { return Iterate(System.Threading.Interlocked.Increment(ref Calls)); }
        System.Collections.Generic.IEnumerable<string> Iterate(int call)
        {
            for (int i = 0; i < Lines.Length; i++)
            {
                if (call == 1 && i == PauseBeforeLine) { Paused.Set(); Release.Wait(3000); }
                if (call == 1 && i == ThrowBeforeLine) throw new System.IO.IOException("테스트: 디스크 읽기 실패");
                yield return Lines[i];
            }
        }
    }

    sealed class Atlases
    {
        public int Calls;
        public bool PauseFirst;
        public readonly System.Threading.ManualResetEventSlim Paused = new System.Threading.ManualResetEventSlim(false);
        public readonly System.Threading.ManualResetEventSlim Release = new System.Threading.ManualResetEventSlim(false);
        public IconAtlas Build()
        {
            int c = System.Threading.Interlocked.Increment(ref Calls);
            if (c == 1 && PauseFirst) { Paused.Set(); Release.Wait(3000); }
            return new IconAtlas(c);
        }
    }

    sealed class Worker
    {
        public System.Threading.Thread T;
        public volatile bool Done;
        public string Error;
        public object Result;
    }

    static Worker Start(System.Func<object> body)
    {
        var w = new Worker();
        w.T = StartThread(() =>
        {
            try { w.Result = body(); }
            catch (System.Exception e) { w.Error = e.GetType().Name; }
            w.Done = true;
        });
        return w;
    }

    // w 가 끝났거나, 대기 상태(WaitSleepJoin)를 60ms 동안 계속 유지할 때까지 최대 1500ms 기다린다. 끝났으면 true.
    static bool DoneOrBlocked(Worker w)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        long blockedSince = -1;
        while (sw.ElapsedMilliseconds < 1500)
        {
            if (w.Done) return true;
            bool blocked = (w.T.ThreadState & System.Threading.ThreadState.WaitSleepJoin) != 0;
            if (!blocked) blockedSince = -1;
            else if (blockedSince < 0) blockedSince = sw.ElapsedMilliseconds;
            else if (sw.ElapsedMilliseconds - blockedSince >= 60) break;
            System.Threading.Thread.Sleep(2);
        }
        return w.Done;
    }

    static string Describe(Worker w) { return w.Error != null ? "예외 " + w.Error : "결과 " + w.Result; }

    static GameDataRegistry Make(Source s, Atlases a) { return new GameDataRegistry(s.Read, a.Build); }

    public static void Main()
    {
        Run("single-thread-basics", () =>
        {
            var s = new Source(); var a = new Atlases();
            var r = Make(s, a);
            if (s.Calls != 0 || a.Calls != 0) return "생성자에서 이미 로드함(아이템 읽기 " + s.Calls + "회, 아틀라스 생성 " + a.Calls + "회): 처음 접근할 때 로드해야 함";
            string name;
            if (!r.TryGetItemName(2, out name) || name != "Shield") return "TryGetItemName(2) 기대 true, \"Shield\" / 결과 " + name;
            if (r.TryGetItemName(99, out name) || name != null) return "없는 id 99 의 TryGetItemName 기대 false, null";
            if (r.ItemCount != 3) return "ItemCount 기대 3 / 결과 " + r.ItemCount;
            r.TryGetItemName(1, out name);
            if (s.Calls != 1) return "여러 번 조회했는데 아이템 읽기가 " + s.Calls + "회 실행됨(기대 1회)";
            if (a.Calls != 0) return "아이템만 조회했는데 아틀라스가 생성됨";
            var x = r.Atlas; var y = r.Atlas;
            if (x == null || !ReferenceEquals(x, y) || a.Calls != 1) return "Atlas 를 두 번 읽었을 때 기대: 같은 인스턴스, 생성 1회 / 결과 생성 " + a.Calls + "회";
            return null;
        });

        Run("waiter-sees-complete-table", () =>
        {
            // A 가 첫 줄을 읽은 뒤 멈춰 있는 동안 B 가 ItemCount 를 읽는다. B 는 로드가 끝날 때까지 기다렸다가 3 을 받아야 한다.
            var s = new Source { PauseBeforeLine = 1 }; var a = new Atlases();
            var r = Make(s, a);
            var wa = Start(() => r.ItemCount);
            if (!s.Paused.Wait(2000)) return "A 스레드의 로드가 시작되지 않음";
            var wb = Start(() => r.ItemCount);
            bool earlyB = DoneOrBlocked(wb);
            s.Release.Set();
            if (!wa.T.Join(2000) || !wb.T.Join(2000)) return "로드가 끝난 뒤에도 스레드가 끝나지 않음";
            if (earlyB) return "A 가 로드 중(첫 줄만 읽음)인데 B 가 기다리지 않고 반환함(" + Describe(wb) + ", 아이템 읽기 " + s.Calls + "회): " + (s.Calls > 1 ? "B 가 기다리지 않고 따로 로드함" : "채우는 중인 테이블이 공개됨");
            if (wa.Error != null || wb.Error != null || (int)wa.Result != 3 || (int)wb.Result != 3) return "A, B 의 ItemCount 기대 3, 3 / A " + Describe(wa) + ", B " + Describe(wb);
            return s.Calls == 1 ? null : "아이템 읽기 기대 1회 / 결과 " + s.Calls + "회";
        });

        Run("load-runs-once-under-contention", () =>
        {
            // A 가 첫 줄을 읽기 직전(락 안)에 멈춘 사이 B 도 처음 접근한다. B 는 기다렸다가 A 가 만든 테이블을 써야 한다.
            var s = new Source { PauseBeforeLine = 0 }; var a = new Atlases();
