            if (earlyB) return "A 가 로드 중인데 B 가 기다리지 않고 반환함(" + Describe(wb) + ", 아이템 읽기 " + s.Calls + "회): " + (s.Calls > 1 ? "B 가 기다리지 않고 따로 로드함" : "로드 중인 테이블이 공개됨");
            if (s.Calls != 1) return "두 스레드가 처음 접근했을 때 아이템 읽기가 " + s.Calls + "회 실행됨(기대 1회): 락을 얻은 뒤 다시 확인하지 않음";
            if (wa.Error != null || wb.Error != null || (string)wa.Result != "Sword" || (string)wb.Result != "Potion") return "기대 A = Sword, B = Potion / A " + Describe(wa) + ", B " + Describe(wb);
            return null;
        });

        Run("atlas-built-once", () =>
        {
            // A 의 아틀라스 생성이 멈춰 있는 동안 B 가 Atlas 를 읽는다. 생성 함수는 한 번만 실행되어야 한다.
