            if (callsWhilePaused > 1 || a.Calls != 1) return "두 스레드가 동시에 Atlas 를 읽자 생성 함수가 " + a.Calls + "회 실행됨(기대 1회): 버려진 아틀라스의 GPU 메모리가 샌다";
            if (earlyB) return "A 가 아틀라스를 만드는 중인데 B 가 기다리지 않고 반환함";
            return ReferenceEquals(wa.Result, wb.Result) ? null : "두 스레드가 서로 다른 아틀라스 인스턴스를 받음";
        });

        Run("failed-load-is-retried", () =>
        {
            // 첫 로드는 두 번째 줄 직전에 IOException. 예외는 그 호출자에게 그대로 전파되고, 다음 호출은 다시 로드해야 한다.
            var s = new Source { ThrowBeforeLine = 1 }; var a = new Atlases();
            var r = Make(s, a);
            string name;
            try { r.TryGetItemName(1, out name); return "첫 로드가 실패했는데 TryGetItemName 이 예외 없이 반환함"; }
            catch (System.IO.IOException) { }
            try
            {
                if (!r.TryGetItemName(2, out name) || name != "Shield") return "실패 뒤 다시 호출한 TryGetItemName(2) 기대 true, \"Shield\" / 결과 false, " + (name ?? "null") + " (아이템 읽기 " + s.Calls + "회): 실패한 로드의 반쪽 테이블이 남음";
            }
            catch (System.IO.IOException) { return "실패 뒤 다시 호출해도 같은 IOException 이 남(아이템 읽기 " + s.Calls + "회): 실패가 캐시되어 다시 로드하지 않음"; }
            if (r.ItemCount != 3) return "다시 로드한 뒤 ItemCount 기대 3 / 결과 " + r.ItemCount;
            return s.Calls == 2 ? null : "아이템 읽기 기대 2회(실패 1 + 성공 1) / 결과 " + s.Calls + "회";
        });
    }
}

