problems.solutionCode:
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Threading;

// 제출한 작업 하나의 완료를 기다리는 핸들.
public sealed class JobHandle
{
    private readonly object _gate = new object();
    private readonly Action _job;
    private bool _done;            // _gate 로 보호
    private Exception _error;      // _done 이 true 가 되기 전에 기록한다

    internal JobHandle(Action job)
    {
        _job = job;
    }

    // 작업이 끝났으면(성공이든 예외든) true.
    public bool IsCompleted
    {
        get { lock (_gate) { return _done; } }
    }

    // 작업이 끝날 때까지 최대 timeoutMs 기다린다. 끝났으면 true, 시간이 다 되면 false.
    // 작업이 예외로 끝났다면 그 예외를 InnerException 으로 담은 AggregateException 을 던진다(부를 때마다).
    // timeoutMs: 0 = 기다리지 않음, Timeout.Infinite(-1) = 무한, -1 보다 작으면 ArgumentOutOfRangeException.
    public bool Wait(int timeoutMs)
    {
        if (timeoutMs < Timeout.Infinite) throw new ArgumentOutOfRangeException(nameof(timeoutMs));
        lock (_gate)
        {
            long startedAt = Stopwatch.GetTimestamp();
            while (!_done)
            {
                int waitMs = Timeout.Infinite;
                if (timeoutMs != Timeout.Infinite)
                {
                    // 깨어날 때마다 남은 시간만 다시 기다린다(올림: 제한 시간보다 일찍 포기하지 않는다)
                    double remaining = timeoutMs - Stopwatch.GetElapsedTime(startedAt).TotalMilliseconds;
                    if (remaining <= 0) return false;
                    waitMs = (int)Math.Ceiling(remaining);
                }
                Monitor.Wait(_gate, waitMs);
            }
        }
        if (_error != null) throw new AggregateException(_error);
        return true;
    }

    // 작업 스레드에서만 호출한다. 작업의 예외는 여기서 잡아 기록하므로 작업 스레드를 죽이지 않는다.
    internal void Run()
    {
        try { _job(); }
        catch (Exception e) { _error = e; }
        lock (_gate)
        {
            _done = true;
            Monitor.PulseAll(_gate);   // 이 핸들을 기다리는 스레드가 여럿일 수 있다
        }
    }
}

// 생성할 때 만든 전용 스레드 workerCount 개로만 작업을 실행하는 고정 크기 스레드 풀.
// 오래 막히는 작업이 프로세스 공용 ThreadPool 의 스레드를 붙잡아 다른 작업이 시작되지 못하는 일을 피하려고 전용 스레드를 쓴다.
public sealed class FixedThreadPool : IDisposable
{
    private readonly object _gate = new object();
    private readonly Queue<JobHandle> _queue = new Queue<JobHandle>();   // _gate 로 보호
    private bool _closed;                                                // _gate 로 보호
    private readonly Thread[] _workers;

    // workerCount 가 1 보다 작으면 ArgumentOutOfRangeException. 작업 스레드 workerCount 개를 만들어 시작한다.
    public FixedThreadPool(int workerCount)
    {
        if (workerCount < 1) throw new ArgumentOutOfRangeException(nameof(workerCount));
        _workers = new Thread[workerCount];
        for (int i = 0; i < workerCount; i++)
        {
            _workers[i] = new Thread(WorkerLoop) { IsBackground = true, Name = "pool-worker-" + i };
            _workers[i].Start();
        }
    }

    public int WorkerCount => _workers.Length;

    // 작업을 큐에 넣고 곧바로 핸들을 돌려준다(호출한 스레드에서 실행하지 않는다).
    // job 이 null 이면 ArgumentNullException, Dispose 가 호출된 뒤에는 ObjectDisposedException.
    public JobHandle Submit(Action job)
    {
        if (job == null) throw new ArgumentNullException(nameof(job));
        var handle = new JobHandle(job);
        lock (_gate)
        {
            // 닫혔는지 확인하는 것과 넣는 것을 같은 락 안에서 한다: 받아 놓고 실행하지 않는 작업이 생기지 않는다
            if (_closed) throw new ObjectDisposedException(nameof(FixedThreadPool));
            _queue.Enqueue(handle);
            // 이 락에서 기다리는 것은 작업 스레드뿐이고 작업 하나는 스레드 하나만 처리하면 되므로 하나만 깨운다
            Monitor.Pulse(_gate);
        }
        return handle;
    }

    // 새 작업을 더 받지 않고, 이미 큐에 들어온 작업을 모두 실행한 뒤 작업 스레드를 모두 종료하고 반환한다.
    // 여러 번 불러도 되며 두 번째부터는 아무 일도 하지 않는다.
    public void Dispose()
    {
        lock (_gate)
        {
            if (_closed) return;
            _closed = true;
            Monitor.PulseAll(_gate);   // 잠든 작업 스레드를 모두 깨워 큐를 비운 뒤 끝나게 한다
        }
        foreach (Thread t in _workers) t.Join();
    }

    private void WorkerLoop()
    {
        while (true)
        {
            JobHandle next;
            lock (_gate)
            {
                // 큐가 비어 있고 닫히지 않았으면 잔다(폴링하지 않는다). 깨어날 때마다 조건을 다시 본다.
                while (_queue.Count == 0 && !_closed) Monitor.Wait(_gate);
                if (_queue.Count == 0) return;   // 닫혔고 남은 작업도 없다
                next = _queue.Dequeue();
            }
            next.Run();   // 락 밖에서 실행한다: 작업이 오래 걸려도 Submit 과 다른 작업 스레드를 막지 않는다
        }
    }
}

