public static class __Judge
{
    static readonly System.Diagnostics.Stopwatch Clock = System.Diagnostics.Stopwatch.StartNew();
    const int TotalBudgetMs = 9000, CaseBudgetMs = 3000, StackBytes = 256 * 1024;

    // 채점 환경은 동시에 살아 있는 스레드를 6개까지만 허용한다: 케이스 스레드 1 + 풀의 작업 스레드 최대 3 + 보조 스레드 최대 2.
    // Join 이 끝난 스레드도 OS 에서 잠깐 남아 있을 수 있으므로, 케이스 사이에 스레드 수가 처음 값으로 돌아오기를 잠깐 기다리고
    // 채점 쪽 스레드는 생성이 일시적으로 실패(OutOfMemoryException)하면 잠깐 뒤 다시 만든다.
    static int BaseThreads = int.MaxValue;
    static int LiveThreads() { try { return System.Diagnostics.Process.GetCurrentProcess().Threads.Count; } catch { return -1; } }
    static void Settle()
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < 200) { int n = LiveThreads(); if (n < 0 || n <= BaseThreads) return; System.Threading.Thread.Sleep(2); }
    }
    static System.Threading.Thread StartThread(System.Threading.ThreadStart body)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (true)
        {
            var t = new System.Threading.Thread(body, StackBytes) { IsBackground = true };
            try { t.Start(); return t; }
            catch (System.OutOfMemoryException) { if (sw.ElapsedMilliseconds > 300) throw; System.Threading.Thread.Sleep(5); }
        }
    }

    // 케이스마다 별도 스레드에서 실행하고, 제한 시간 안에 끝나지 않으면 [FAIL] 로 보고한다(채점기가 멈추지 않게 한다).
    static void Run(string id, System.Func<string> body, int caseBudgetMs = CaseBudgetMs)
    {
        string err;
        Settle();
        int budget = (int)System.Math.Min(caseBudgetMs, TotalBudgetMs - Clock.ElapsedMilliseconds);
        if (budget <= 0) err = "앞선 케이스들이 제한 시간을 다 써서 실행하지 못함";
        else
        {
            string result = null;
            try
            {
                var t = StartThread(() =>
                {
                    try { result = body(); }
                    catch (System.Exception e) { result = "예외 발생: " + e.GetType().Name; }
                });
                err = t.Join(budget) ? result : "시간 초과(" + budget + "ms): 호출이 돌아오지 않음(작업 스레드가 깨어나지 않았거나 Dispose 가 끝나지 않음)";
            }
            catch (System.Exception e) { err = "케이스 스레드를 만들 수 없음(" + e.GetType().Name + "): 앞선 케이스의 작업 스레드가 끝나지 않고 남아 있음"; }
        }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Threading.Thread Helper(System.Action body)
    {
        return StartThread(() => { try { body(); } catch { } });
    }

    // cond 가 참이 될 때까지 최대 ms 기다린다(테스트 쪽의 관찰용 대기).
    static bool Eventually(System.Func<bool> cond, int ms)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (!cond()) { if (sw.ElapsedMilliseconds > ms) return false; System.Threading.Thread.Sleep(1); }
        return true;
    }

    static bool Throws<T>(System.Action a) where T : System.Exception
    {
        try { a(); return false; } catch (T) { return true; }
    }

    public static void Main()
    {
        BaseThreads = LiveThreads() + 1;   // +1: 첫 출력 때 런타임이 신호 처리용 스레드를 하나 더 만든다
        Run("arguments-and-basics", () =>
        {
            if (!Throws<System.ArgumentOutOfRangeException>(() => new FixedThreadPool(0))) return "workerCount 0 에 ArgumentOutOfRangeException 이 나지 않음";
            var pool = new FixedThreadPool(2);
            try
            {
                if (pool.WorkerCount != 2) return "WorkerCount 기대 2 / 결과 " + pool.WorkerCount;
                if (!Throws<System.ArgumentNullException>(() => pool.Submit(null))) return "Submit(null) 에 ArgumentNullException 이 나지 않음";
                int caller = System.Threading.Thread.CurrentThread.ManagedThreadId, ranOn = -1;
                var h = pool.Submit(() => { ranOn = System.Threading.Thread.CurrentThread.ManagedThreadId; });
                if (!h.Wait(2000)) return "간단한 작업이 2000ms 안에 끝나지 않음";
                if (ranOn == caller) return "작업이 Submit 을 호출한 스레드에서 실행됨(작업 스레드에서 실행해야 함)";
                if (!h.IsCompleted || !h.Wait(0) || !h.Wait(System.Threading.Timeout.Infinite)) return "끝난 작업의 IsCompleted / Wait(0) / Wait(Infinite) 가 true 가 아님";
                if (!Throws<System.ArgumentOutOfRangeException>(() => h.Wait(-2))) return "Wait(-2) 에 ArgumentOutOfRangeException 이 나지 않음";
            }
            finally { pool.Dispose(); }
            return null;
        });

        Run("runs-on-exactly-n-workers", () =>
        {
            // 작업 스레드 3개: 막히는 작업 3개는 모두 동시에 시작해야 하고, 4번째는 셋 중 하나가 풀릴 때까지 시작하면 안 된다.
            var pool = new FixedThreadPool(3);
            var gate = new System.Threading.ManualResetEventSlim(false);
            try
            {
                int started = 0;
                var ids = new System.Collections.Generic.HashSet<int>();
                System.Action blocking = () =>
                {
                    lock (ids) ids.Add(System.Threading.Thread.CurrentThread.ManagedThreadId);
                    System.Threading.Interlocked.Increment(ref started);
                    gate.Wait(2500);
                };
                var hs = new JobHandle[4];
                for (int i = 0; i < 3; i++) hs[i] = pool.Submit(blocking);
                if (!Eventually(() => System.Threading.Volatile.Read(ref started) == 3, 1500)) return "작업 스레드가 3개인데 막히는 작업 3개 중 " + System.Threading.Volatile.Read(ref started) + "개만 시작됨(작업 스레드가 모자라거나 깨어나지 않음)";
                int fourth = 0;
                hs[3] = pool.Submit(() => { lock (ids) ids.Add(System.Threading.Thread.CurrentThread.ManagedThreadId); System.Threading.Interlocked.Increment(ref fourth); });
                System.Threading.Thread.Sleep(200);
                if (System.Threading.Volatile.Read(ref fourth) != 0) return "작업 스레드 3개가 모두 막혀 있는데 4번째 작업이 실행됨(동시에 workerCount 개보다 많이 실행함)";
                if (hs[3].IsCompleted) return "실행되지 않은 4번째 작업의 IsCompleted 가 true";
                gate.Set();
                foreach (var h in hs) if (!h.Wait(2000)) return "막힘이 풀린 뒤에도 작업이 2000ms 안에 끝나지 않음";
                if (fourth != 1) return "4번째 작업 실행 횟수 기대 1 / 결과 " + fourth;
                lock (ids)
                {
                    if (ids.Contains(System.Threading.Thread.CurrentThread.ManagedThreadId)) return "작업이 Submit 을 호출한 스레드에서 실행됨";
                    if (ids.Count != 3) return "작업 4개가 실행된 스레드 수 기대 3(작업 스레드 재사용) / 결과 " + ids.Count;
                }
            }
            finally { gate.Set(); pool.Dispose(); }
            return null;
        });

        Run("fifo-with-one-worker", () =>
        {
            var pool = new FixedThreadPool(1);
            var gate = new System.Threading.ManualResetEventSlim(false);
            try
            {
                var order = new System.Collections.Generic.List<int>();
                pool.Submit(() => gate.Wait(2500));
                JobHandle last = null;
                for (int i = 0; i < 50; i++) { int k = i; last = pool.Submit(() => { lock (order) order.Add(k); }); }
                gate.Set();
                if (!last.Wait(2000)) return "작업 51개가 2000ms 안에 끝나지 않음";
                lock (order)
                {
                    for (int i = 0; i < 50; i++) if (order.Count != 50 || order[i] != i) return "작업 스레드 1개에서 실행 순서가 제출 순서와 다름: " + string.Join(",", order.GetRange(0, System.Math.Min(order.Count, 8))) + "...";
                }
            }
            finally { gate.Set(); pool.Dispose(); }
            return null;
        });

        Run("wait-timeout-and-many-waiters", () =>
        {
            var pool = new FixedThreadPool(1);
            var gate = new System.Threading.ManualResetEventSlim(false);
            try
            {
                var h = pool.Submit(() => gate.Wait(2500));
                var sw = System.Diagnostics.Stopwatch.StartNew();
                bool r = h.Wait(150);
                long ms = sw.ElapsedMilliseconds;
                if (r) return "끝나지 않은 작업의 Wait(150) 이 true";
                if (ms < 100 || ms > 1500) return "끝나지 않은 작업의 Wait(150) 기대 약 150ms 뒤 false / 결과 " + ms + "ms 뒤 반환";
                if (h.IsCompleted) return "끝나지 않은 작업의 IsCompleted 가 true";
                int returned = 0;
                bool ok1 = false, ok2 = false;
                var w1 = Helper(() => { ok1 = h.Wait(System.Threading.Timeout.Infinite); System.Threading.Interlocked.Increment(ref returned); });
                var w2 = Helper(() => { ok2 = h.Wait(2500); System.Threading.Interlocked.Increment(ref returned); });
                System.Threading.Thread.Sleep(80);
                if (System.Threading.Volatile.Read(ref returned) != 0) return "작업이 끝나지 않았는데 다른 스레드의 Wait 가 반환함";
                gate.Set();
                if (!w1.Join(1500) || !w2.Join(1500)) return "작업이 끝났는데 같은 핸들을 기다리던 두 스레드가 깨어나지 않음(한 스레드만 깨움)";
                if (!ok1 || !ok2) return "작업이 끝난 뒤 다른 스레드의 Wait 가 false";
            }
            finally { gate.Set(); pool.Dispose(); }
            return null;
        });

        Run("many-jobs-no-loss", () =>
        {
            // 작업 스레드 3개가 꺼내는 동안 제출 스레드 3개(케이스 스레드 + 보조 스레드 2개)가 게이트에서 동시에 출발해 넣는다.
            // 6라운드 x 18,000개: 작업이 유실되거나 두 번 실행되면 안 된다(락 없는 큐의 경쟁을 드러내려고 여러 라운드 반복한다).
            const int submitters = 3, per = 6000, total = submitters * per;
            var pool = new FixedThreadPool(3);
            try
            {
                var sw = System.Diagnostics.Stopwatch.StartNew();
                for (int round = 0; round < 6; round++)
                {
                    var runs = new int[total];
                    var handles = new JobHandle[total];
                    var go = new System.Threading.ManualResetEventSlim(false);
                    string submitErr = null;
                    System.Action<int> submitRange = part =>
                    {
                        go.Wait(1000);
                        try { for (int i = part * per; i < (part + 1) * per; i++) { int k = i; handles[i] = pool.Submit(() => System.Threading.Interlocked.Increment(ref runs[k])); } }
                        catch (System.Exception e) { submitErr = e.GetType().Name; }
                    };
                    var h1 = Helper(() => submitRange(1));
                    var h2 = Helper(() => submitRange(2));
                    System.Threading.Thread.Sleep(20);
                    go.Set();
                    submitRange(0);
                    if (!h1.Join(2000) || !h2.Join(2000)) return "보조 스레드의 Submit 이 2000ms 안에 끝나지 않음";
                    if (submitErr != null) return "세 스레드가 동시에 Submit 하다 예외: " + submitErr;
                    for (int i = 0; i < total; i++)
                    {
                        int left = 3600 - (int)sw.ElapsedMilliseconds;
                        if (left < 1 || handles[i] == null || !handles[i].Wait(left)) return (round + 1) + "라운드: 작업 " + total + "개가 제한 시간 안에 모두 끝나지 않음(" + i + "번째에서 멈춤: 작업 유실 또는 깨우기 누락)";
                    }
                    for (int i = 0; i < total; i++) if (runs[i] != 1) return (round + 1) + "라운드: 작업 " + i + " 이 " + runs[i] + "번 실행됨(기대 1번)";
                }
                // 잠든 작업 스레드를 깨웠는데 다른 작업 스레드가 그 작업을 먼저 꺼내 가는 상황을 반복해 만든다:
                // 작업 A 가 바쁘게 도는 동안 B 를 넣고(잠든 스레드 하나가 깨어남) 곧바로 A 를 끝내면, A 를 돌던 스레드가 대개 B 를 먼저 가져간다.
                for (int r = 0; r < 100; r++)
                {
                    int phase = 0;   // 0: 대기, 1: A 실행 중, 2: A 를 끝내라
                    var a = pool.Submit(() => { System.Threading.Volatile.Write(ref phase, 1); var spin = System.Diagnostics.Stopwatch.StartNew(); while (System.Threading.Volatile.Read(ref phase) != 2 && spin.ElapsedMilliseconds < 500) { } });
                    if (!System.Threading.SpinWait.SpinUntil(() => System.Threading.Volatile.Read(ref phase) == 1, 1000)) return "작업 A 가 1000ms 안에 시작되지 않음(" + r + "번째 반복)";
                    var b = pool.Submit(() => { });
                    System.Threading.Volatile.Write(ref phase, 2);
                    int left = 3600 - (int)sw.ElapsedMilliseconds;
                    if (left < 1 || !a.Wait(left) || !b.Wait(System.Math.Max(1, 3600 - (int)sw.ElapsedMilliseconds))) return (r + 1) + "번째 반복에서 작업이 제한 시간 안에 끝나지 않음(작업 스레드가 모두 끝나 버렸거나 깨우기 누락)";
                }
                // 수많은 깨우기를 거친 뒤에도 작업 스레드 3개가 모두 살아 있어야 한다(깨어났는데 큐가 비었다고 끝나 버리는 루프를 잡는다).
                var hold = new System.Threading.ManualResetEventSlim(false);
                int busy = 0;
                for (int i = 0; i < 3; i++) pool.Submit(() => { System.Threading.Interlocked.Increment(ref busy); hold.Wait(1500); });
                bool allAlive = Eventually(() => System.Threading.Volatile.Read(ref busy) == 3, 1000);
                int busyNow = System.Threading.Volatile.Read(ref busy);
                hold.Set();
                if (!allAlive) return "작업 10만여 개를 처리한 뒤 막히는 작업 3개 중 " + busyNow + "개만 동시에 시작됨: 작업 스레드가 도중에 끝나 버림(깨어났을 때 큐가 비어 있으면 종료하는 루프로 보임)";
            }
            finally { pool.Dispose(); }
            return null;
        }, 4000);

        Run("dispose-drains-queue-and-stops-workers", () =>
        {
            var pool = new FixedThreadPool(1);
            var gate = new System.Threading.ManualResetEventSlim(false);
            System.Threading.Thread worker = null;
            int ran = 0;
            var hs = new JobHandle[6];
            hs[0] = pool.Submit(() => { worker = System.Threading.Thread.CurrentThread; gate.Wait(2500); System.Threading.Interlocked.Increment(ref ran); });
            for (int i = 1; i < 6; i++) hs[i] = pool.Submit(() => System.Threading.Interlocked.Increment(ref ran));
            if (!Eventually(() => System.Threading.Volatile.Read(ref worker) != null, 1500)) { gate.Set(); return "첫 작업이 시작되지 않음"; }
            bool disposed = false;
            var d = Helper(() => { pool.Dispose(); System.Threading.Volatile.Write(ref disposed, true); });
            // Dispose 가 호출되어 새 작업이 거절될 때까지 기다린 뒤(빈 작업은 받아들여져도 결과에 영향이 없다), 100ms 동안 Dispose 가 반환하지 않는지 본다.
            bool rejected = Eventually(() => Throws<System.ObjectDisposedException>(() => pool.Submit(() => { })), 1500);
            System.Threading.Thread.Sleep(100);
            bool early = System.Threading.Volatile.Read(ref disposed);
            gate.Set();
            if (!d.Join(2000)) return "큐가 비었는데도 Dispose 가 2000ms 안에 반환하지 않음(작업 스레드를 깨우지 않았을 수 있음)";
            if (early) return "큐에 작업 5개가 남아 있는데 Dispose 가 먼저 반환함(작업을 다 실행하고 스레드가 끝난 뒤 반환해야 함)";
            if (!rejected) return "Dispose 를 호출한 뒤의 Submit 이 ObjectDisposedException 을 던지지 않음";
            if (System.Threading.Volatile.Read(ref ran) != 6) return "Dispose 전에 큐에 들어간 작업 6개 중 " + ran + "개만 실행됨(남은 작업을 버림)";
            foreach (var h in hs) if (!h.IsCompleted) return "Dispose 가 반환했는데 끝나지 않은 핸들이 있음";
            if (worker.IsAlive) return "Dispose 가 반환했는데 작업 스레드가 아직 살아 있음";
            try { pool.Dispose(); } catch (System.Exception e) { return "Dispose 를 두 번 호출하자 예외: " + e.GetType().Name; }
            return Throws<System.ObjectDisposedException>(() => pool.Submit(() => { })) ? null : "Dispose 뒤의 Submit 이 ObjectDisposedException 을 던지지 않음";
        });

        // 처리되지 않은 예외는 프로세스를 끝내므로 이 케이스는 마지막에 둔다.
        Run("exception-propagates-worker-survives", () =>
        {
            var pool = new FixedThreadPool(1);
            try
            {
                var boom = new System.InvalidOperationException("테스트: 작업 실패");
                int firstThread = -1;
                var bad = pool.Submit(() => { firstThread = System.Threading.Thread.CurrentThread.ManagedThreadId; throw boom; });
                for (int round = 0; round < 6; round++)
                {
                    try { bad.Wait(2000); return "예외로 끝난 작업의 Wait 가 예외 없이 반환함(" + (round + 1) + "번째 호출)"; }
                    catch (System.AggregateException ae) { if (!ReferenceEquals(ae.InnerException, boom)) return "AggregateException.InnerException 이 작업이 던진 예외 객체가 아님"; }
                    catch (System.Exception e) { return "Wait 가 AggregateException 이 아닌 " + e.GetType().Name + " 를 던짐"; }
                }
                if (!bad.IsCompleted) return "예외로 끝난 작업의 IsCompleted 가 false";
                int secondThread = -1;
                var good = pool.Submit(() => { secondThread = System.Threading.Thread.CurrentThread.ManagedThreadId; });
                if (!good.Wait(2000)) return "예외 뒤에 제출한 작업이 실행되지 않음(작업 스레드가 죽었을 수 있음)";
                if (secondThread != firstThread) return "작업 스레드 1개짜리 풀에서 예외 뒤의 작업이 다른 스레드에서 실행됨(죽은 스레드를 새로 만든 것으로 보임)";
            }
            finally { pool.Dispose(); }
            return null;
        });
    }
}

