using System;
using System.Buffers.Binary;
using System.IO;

// 저장 장치 추상화. 게임에서는 File/FileStream 으로 구현하고, 테스트에서는 전원 차단을 흉내 내는 메모리 구현을 쓴다.
// 이 문제의 모델: 이름 작업(새 파일 생성, Move, Delete)은 호출이 끝나면 바로 영속된다고 가정한다.
// 파일 내용은 FlushToDisk 를 부르기 전까지 OS 캐시에만 있을 수 있다.
public interface IFileSystem
{
    bool Exists(string path);
    // 실행 중인 프로세스가 보는 현재 내용(OS 캐시 포함)의 복사본. 없으면 FileNotFoundException.
    byte[] ReadAll(string path);
    // 파일을 만들거나 내용을 통째로 바꾼다. 반환되어도 내용은 아직 저장 장치에 없을 수 있다.
    void WriteAll(string path, byte[] data);
    // FileStream.Flush(true) / fsync 에 해당: 이 파일의 지금 내용을 저장 장치에 기록한 뒤 반환한다.
    void FlushToDisk(string path);
    // POSIX rename 처럼 동작: dst 가 있으면 교체하며, 그동안에도 dst 는 이전 파일이나 새 파일 중 하나를 가리킨다.
    void Move(string src, string dst);
    // 없으면 아무 일도 하지 않는다.
    void Delete(string path);
}

// CRC-32 (CRC-32/ISO-HDLC: zlib·PNG 와 같은 매개변수). 반사 다항식 0xEDB88320, 초기값·최종 XOR 0xFFFFFFFF.
// 검사값: ASCII "123456789" -> 0xCBF43926. 이 문제에서는 주어진 그대로 쓴다.
public static class Crc32
{
    public static uint Compute(ReadOnlySpan<byte> data)
    {
        uint crc = 0xFFFFFFFFu;
        foreach (byte b in data)
        {
            crc ^= b;
            for (int k = 0; k < 8; k++)
                crc = (crc & 1) != 0 ? (crc >> 1) ^ 0xEDB88320u : crc >> 1;
        }
        return ~crc;
    }
}

public enum SaveSource { None, Main, Backup }

public readonly struct LoadResult
{
    public LoadResult(SaveSource source, byte[] payload) { Source = source; Payload = payload; }
    public SaveSource Source { get; }
    public byte[] Payload { get; }   // Source == None 이면 null
}

public sealed class SaveStore
{
    public const string MainPath = "save.dat";
    public const string TempPath = "save.tmp";
    public const string BackupPath = "save.bak";
    public const int HeaderSize = 12;   // 매직 4 + 본문 길이 4 + 본문 CRC-32 4

    private static ReadOnlySpan<byte> Magic => "GSV1"u8;

    private readonly IFileSystem _fs;

    public SaveStore(IFileSystem fs)
    {
        _fs = fs ?? throw new ArgumentNullException(nameof(fs));
    }

    // [0..4) "GSV1"  [4..8) 본문 길이(int32 LE)  [8..12) 본문 CRC-32(uint32 LE)  [12..) 본문
    public static byte[] Encode(ReadOnlySpan<byte> payload)
    {
        var file = new byte[HeaderSize + payload.Length];
        Magic.CopyTo(file);
        BinaryPrimitives.WriteInt32LittleEndian(file.AsSpan(4), payload.Length);
        BinaryPrimitives.WriteUInt32LittleEndian(file.AsSpan(8), Crc32.Compute(payload));
        payload.CopyTo(file.AsSpan(HeaderSize));
        return file;
    }

    // 매직, 길이, 체크섬이 모두 맞을 때만 true 와 본문 복사본을 돌려준다. 어떤 입력에도 예외를 던지지 않는다.
    public static bool TryDecode(byte[] file, out byte[] payload)
    {
        payload = null;
        if (file == null || file.Length < HeaderSize) return false;
        ReadOnlySpan<byte> span = file;
        if (!span.Slice(0, 4).SequenceEqual(Magic)) return false;
        int length = BinaryPrimitives.ReadInt32LittleEndian(span.Slice(4, 4));
        if (length != file.Length - HeaderSize) return false;            // 잘림, 덧붙음, 길이 필드 손상
        ReadOnlySpan<byte> body = span.Slice(HeaderSize);
        if (BinaryPrimitives.ReadUInt32LittleEndian(span.Slice(8, 4)) != Crc32.Compute(body)) return false;
        payload = body.ToArray();
        return true;
    }

    // 새 세이브를 커밋하면 true. 임시 파일 검증에 실패하면 save.dat / save.bak 를 건드리지 않고 false.
    public bool Save(byte[] payload)
    {
        if (payload == null) throw new ArgumentNullException(nameof(payload));
        byte[] file = Encode(payload);

        // 1) 같은 디렉터리의 임시 파일에 전부 쓰고, 저장 장치까지 기록한다.
        _fs.WriteAll(TempPath, file);
        _fs.FlushToDisk(TempPath);

        // 2) 다시 읽어 검증한다. 틀리면 정상본은 그대로 두고 실패를 알린다.
        if (!TryDecode(_fs.ReadAll(TempPath), out byte[] check) || !check.AsSpan().SequenceEqual(payload))
        {
            _fs.Delete(TempPath);
            return false;
        }

        // 3) 지금의 정상본만 백업으로 돌린다. 손상된 save.dat 로 멀쩡한 save.bak 를 덮어쓰지 않는다.
        if (TryRead(MainPath, out _)) _fs.Move(MainPath, BackupPath);

        // 4) 커밋 지점: rename 한 번으로 새 세이브가 save.dat 가 된다.
        _fs.Move(TempPath, MainPath);
        return true;
    }

    // 읽기만 한다: save.dat -> save.bak 순서로 검증을 통과한 첫 파일을 돌려준다.
    // save.tmp 는 중단된 저장의 흔적이므로 쓰지 않는다(다음 Save 가 덮어쓴다).
    public LoadResult Load()
    {
        if (TryRead(MainPath, out byte[] payload)) return new LoadResult(SaveSource.Main, payload);
        if (TryRead(BackupPath, out payload)) return new LoadResult(SaveSource.Backup, payload);
        return new LoadResult(SaveSource.None, null);
    }

    private bool TryRead(string path, out byte[] payload)
    {
        payload = null;
        return _fs.Exists(path) && TryDecode(_fs.ReadAll(path), out payload);
    }
}

