{{USER_CODE}}

public static class __Judge
{
    sealed class Crash : System.Exception { }
    sealed class Node { public byte[] Durable = new byte[0]; public byte[] Cached; }

    // 메모리 파일 시스템. 이름 작업은 즉시 영속, 내용은 FlushToDisk 전까지 캐시에만 있다.
    // CrashAt 번째 변경 작업에서 프로세스가 죽는다(WriteAll 이면 앞 절반만 쓰인 채). 그 뒤 모든 호출은 Crash.
    sealed class MemFs : IFileSystem
    {
        public System.Collections.Generic.Dictionary<string, Node> Dir = new System.Collections.Generic.Dictionary<string, Node>();
        public int Ops, CrashAt = -1; public bool Dead; public string CorruptNextWriteOf;
        public System.Collections.Generic.List<string> Log = new System.Collections.Generic.List<string>();
        void Alive() { if (Dead) throw new Crash(); }
        bool Step(string what) { Alive(); Ops++; Log.Add(what); if (Ops != CrashAt) return false; Dead = true; return true; }
        Node Get(string p) { if (!Dir.TryGetValue(p, out var n)) throw new System.IO.FileNotFoundException(p); return n; }
        public bool Exists(string p) { Alive(); return Dir.ContainsKey(p); }
        public byte[] ReadAll(string p) { Alive(); var n = Get(p); return (byte[])(n.Cached ?? n.Durable).Clone(); }
        public void WriteAll(string p, byte[] data)
        {
            var copy = (byte[])data.Clone();
            if (p == CorruptNextWriteOf && copy.Length > 0) { CorruptNextWriteOf = null; copy[copy.Length / 2] ^= 0x5A; }
            bool crash = Step("W " + p);
            if (!Dir.TryGetValue(p, out var n)) Dir[p] = n = new Node();
            n.Cached = crash ? Half(copy) : copy;
            if (crash) throw new Crash();
        }
        public void FlushToDisk(string p) { if (Step("F " + p)) throw new Crash(); var n = Get(p); if (n.Cached != null) { n.Durable = n.Cached; n.Cached = null; } }
        public void Move(string s, string d) { if (Step("M " + s + ">" + d)) throw new Crash(); var n = Get(s); Dir.Remove(s); Dir[d] = n; }
        public void Delete(string p) { if (Step("D " + p)) throw new Crash(); Dir.Remove(p); }
        // 전원 차단: 캐시에만 있던 내용은 mode 0 = 사라짐, 1 = 앞 절반만 남음, 2 = 전부 남음.
        public void PowerLoss(int mode)
        {
            foreach (var n in Dir.Values)
                if (n.Cached != null) { n.Durable = mode == 0 ? n.Durable : mode == 1 ? Half(n.Cached) : n.Cached; n.Cached = null; }
            Dead = false; CrashAt = -1;
        }
        public void Put(string p, byte[] durable) { Dir[p] = new Node { Durable = (byte[])durable.Clone() }; }
    }

    static byte[] Half(byte[] a) { var h = new byte[a.Length / 2]; System.Array.Copy(a, h, h.Length); return h; }

    static uint RefCrc(byte[] d, int off)
    {
        uint c = 0xFFFFFFFFu;
        for (int i = off; i < d.Length; i++) { c ^= d[i]; for (int k = 0; k < 8; k++) c = (c & 1) != 0 ? (c >> 1) ^ 0xEDB88320u : c >> 1; }
        return ~c;
    }

    static byte[] RefEncode(byte[] p)
    {
        var f = new byte[12 + p.Length];
        f[0] = (byte)'G'; f[1] = (byte)'S'; f[2] = (byte)'V'; f[3] = (byte)'1';
        System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(new System.Span<byte>(f, 4, 4), p.Length);
        System.Array.Copy(p, 0, f, 12, p.Length);
        System.Buffers.Binary.BinaryPrimitives.WriteUInt32LittleEndian(new System.Span<byte>(f, 8, 4), RefCrc(f, 12));
        return f;
    }

    static byte[] V(int tag, int len) { var a = new byte[len]; for (int i = 0; i < len; i++) a[i] = (byte)(tag * 31 + i * 7); return a; }
    static bool Same(byte[] a, byte[] b) => a != null && b != null && System.MemoryExtensions.SequenceEqual<byte>(a, b);
    static string Name(LoadResult r, byte[][] known)
    {
        if (r.Source == SaveSource.None) return r.Payload == null ? "없음" : "None 인데 Payload 가 null 이 아님";
        for (int i = 0; i < known.Length; i++) if (Same(r.Payload, known[i])) return "v" + i + "(" + r.Source + ")";
        return "알 수 없는 내용(" + r.Source + ")";
    }

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name + " " + e.Message; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static readonly byte[][] Ver = { V(0, 40), V(1, 57), V(2, 33), V(3, 70) };

    // 시작 상태들: (설명, 파일 구성). 저장 전의 "이전 세이브" 는 Load 로 판정한다.
    static MemFs Scenario(int s)
    {
        var fs = new MemFs();
        if (s == 1) fs.Put("save.dat", RefEncode(Ver[0]));
        if (s == 2) { fs.Put("save.dat", RefEncode(Ver[1])); fs.Put("save.bak", RefEncode(Ver[0])); }
        if (s == 3) { var bad = RefEncode(Ver[1]); bad[20] ^= 0x10; fs.Put("save.dat", bad); fs.Put("save.bak", RefEncode(Ver[0])); }
        if (s == 4) { fs.Put("save.bak", RefEncode(Ver[0])); fs.Put("save.tmp", Half(RefEncode(Ver[3]))); }
        if (s == 5) { fs.Put("save.dat", RefEncode(Ver[1])); fs.Put("save.tmp", RefEncode(Ver[3])); }
        return fs;
    }
    static readonly string[] ScenarioName = { "빈 디스크", "save.dat=v0", "dat=v1, bak=v0", "손상된 dat, bak=v0", "dat 없음, bak=v0, 반쪽 tmp", "dat=v1, 남은 tmp=v3" };
    static readonly string[] ModeName = { "캐시 내용 유실", "캐시 내용 절반만 기록", "캐시 내용 전부 기록" };

    // 모든 시작 상태 x 모든 크래시 지점 x 전원 차단 방식에서 Load 가 "이전" 또는 "새" 세이브만 돌려주는지 검사한다.
    static string CrashMatrix(int[] scenarios)
    {
        foreach (int s in scenarios)
        {
            var probe = Scenario(s);
            new SaveStore(probe).Load();
            int before = probe.Ops;
            if (!new SaveStore(probe).Save(Ver[2])) return ScenarioName[s] + ": 정상 Save 가 false 를 반환";
            int ops = probe.Ops - before;
            for (int k = 1; k <= ops + 1; k++)
                for (int mode = 0; mode < 3; mode++)
                {
                    var fs = Scenario(s);
                    LoadResult old = new SaveStore(fs).Load();
                    fs.CrashAt = fs.Ops + k;
                    bool committed = false;
                    try { committed = new SaveStore(fs).Save(Ver[2]); } catch (Crash) { }
                    bool crashed = fs.Dead;
                    string where = ScenarioName[s] + ", " + (crashed ? "Save 의 " + k + "번째 변경 작업(" + fs.Log[fs.Log.Count - 1] + ")에서 크래시" : "Save 완료 후 전원 차단") + ", " + ModeName[mode];
                    fs.PowerLoss(mode);
                    LoadResult now = new SaveStore(fs).Load();
                    if (!crashed && !committed) return where + ": 정상 Save 가 false 를 반환";
                    bool isNew = now.Source != SaveSource.None && Same(now.Payload, Ver[2]);
                    bool isOld = now.Source == SaveSource.None ? old.Source == SaveSource.None : old.Source != SaveSource.None && Same(now.Payload, old.Payload);
                    if (!crashed && !isNew) return where + ": 커밋된 새 세이브(v2) 대신 " + Name(now, Ver) + " 이 로드됨";
                    if (!isNew && !isOld) return where + ": 이전(" + Name(old, Ver) + ") 도 새 세이브(v2) 도 아닌 " + Name(now, Ver) + " 이 로드됨";
                    if (!new SaveStore(fs).Save(Ver[3])) return where + ": 복구 뒤 다음 Save 가 false";
                    var again = new SaveStore(fs).Load();
                    if (!Same(again.Payload, Ver[3])) return where + ": 복구 뒤 다음 Save(v3) 후 Load 결과가 " + Name(again, Ver);
                }
        }
        return null;
    }

    public static void Main()
    {
        Run("format-roundtrip", () =>
        {
            foreach (int len in new[] { 0, 1, 40, 1000 })
            {
                var p = V(5, len);
                byte[] f = SaveStore.Encode(p);
                if (!Same(f, RefEncode(p))) return "본문 " + len + "바이트: Encode 결과가 명세(매직 GSV1, 길이 LE, CRC-32 LE, 본문)와 다름";
                if (!SaveStore.TryDecode(f, out var back) || !Same(back, p)) return "본문 " + len + "바이트: Encode 한 파일을 TryDecode 가 되살리지 못함";
            }
            return null;
        });

        Run("decode-rejects-corruption", () =>
        {
            byte[] good = RefEncode(V(7, 30));
            for (int i = 0; i < good.Length; i++)
                foreach (byte mask in new byte[] { 0x01, 0x80, 0xFF })
                {
                    var bad = (byte[])good.Clone(); bad[i] ^= mask;
                    if (SaveStore.TryDecode(bad, out _)) return i + "번째 바이트를 XOR 0x" + mask.ToString("X2") + " 한 파일을 받아들임";
                }
            for (int len = 0; len < good.Length; len++)
                if (SaveStore.TryDecode(Half2(good, len), out _)) return len + "바이트로 잘린 파일을 받아들임";
            var longer = new byte[good.Length + 1]; System.Array.Copy(good, longer, good.Length);
            if (SaveStore.TryDecode(longer, out _)) return "끝에 1바이트가 덧붙은 파일을 받아들임";
            if (SaveStore.TryDecode(null, out var p0) || p0 != null) return "null 입력에 true 를 반환하거나 payload 가 null 이 아님";
            return null;
        });

        Run("save-load-basic", () =>
        {
            var fs = new MemFs();
            var store = new SaveStore(fs);
            if (store.Load().Source != SaveSource.None) return "빈 디스크에서 Load 의 Source 가 None 이 아님";
            if (!store.Save(Ver[0])) return "Save(v0) 가 false";
            var r = new SaveStore(fs).Load();
            if (r.Source != SaveSource.Main || !Same(r.Payload, Ver[0])) return "Save(v0) 뒤 Load 가 " + Name(r, Ver);
            if (!store.Save(Ver[1])) return "Save(v1) 가 false";
            r = new SaveStore(fs).Load();
            if (r.Source != SaveSource.Main || !Same(r.Payload, Ver[1])) return "Save(v1) 뒤 Load 가 " + Name(r, Ver);
            if (fs.Exists("save.tmp")) return "커밋 뒤 save.tmp 가 남아 있음";
            var cur = fs.ReadAll("save.dat"); cur[13] ^= 0x04; fs.Put("save.dat", cur);
            r = new SaveStore(fs).Load();
            if (r.Source != SaveSource.Backup || !Same(r.Payload, Ver[0])) return "save.dat 이 손상된 뒤 Load 가 백업 v0 이 아니라 " + Name(r, Ver);
            return null;
        });

        Run("committed-save-survives-power-loss", () =>
        {
            var fs = new MemFs();
            for (int i = 0; i < 3; i++)
            {
                if (!new SaveStore(fs).Save(Ver[i])) return "Save(v" + i + ") 가 false";
                fs.PowerLoss(0);
                var r = new SaveStore(fs).Load();
                if (!Same(r.Payload, Ver[i])) return "Save(v" + i + ") 가 true 를 반환한 직후 전원이 나가자(캐시 유실) Load 가 " + Name(r, Ver) + " (rename 전에 FlushToDisk 필요)";
            }
            return null;
        });

        Run("crash-at-every-step", () => CrashMatrix(new[] { 0, 1, 2, 4, 5 }));

        Run("corrupt-main-keeps-backup", () => CrashMatrix(new[] { 3 }));

        Run("verify-before-swap", () =>
        {
            var fs = Scenario(2);
            fs.CorruptNextWriteOf = "save.tmp";
            if (new SaveStore(fs).Save(Ver[2])) return "임시 파일에 손상된 내용이 기록됐는데 Save 가 true 를 반환(다시 읽어 검증하지 않음)";
            var r = new SaveStore(fs).Load();
            if (r.Source != SaveSource.Main || !Same(r.Payload, Ver[1])) return "검증 실패 뒤 Load 가 기존 save.dat(v1) 이 아니라 " + Name(r, Ver);
            if (!fs.Exists("save.bak") || !SaveStore.TryDecode(fs.ReadAll("save.bak"), out var b) || !Same(b, Ver[0])) return "검증 실패한 Save 가 save.bak(v0) 을 바꿈";
            if (!new SaveStore(fs).Save(Ver[3]) || !Same(new SaveStore(fs).Load().Payload, Ver[3])) return "검증 실패 뒤 정상 Save(v3) 가 커밋되지 않음";
            return null;
        });

        Run("load-is-read-only", () =>
        {
            var fs = Scenario(3);
            byte[] dat = fs.ReadAll("save.dat"), bak = fs.ReadAll("save.bak");
            int before = fs.Log.Count;
            var r = new SaveStore(fs).Load();
            if (r.Source != SaveSource.Backup || !Same(r.Payload, Ver[0])) return "손상된 save.dat + 정상 save.bak 에서 Load 가 " + Name(r, Ver);
            for (int i = before; i < fs.Log.Count; i++)
                if (fs.Log[i].Contains("save.dat") || fs.Log[i].Contains("save.bak")) return "Load 가 세이브 파일을 변경함: " + fs.Log[i];
            if (!fs.Exists("save.dat") || !Same(fs.ReadAll("save.dat"), dat) || !Same(fs.ReadAll("save.bak"), bak)) return "Load 뒤 save.dat / save.bak 내용이 바뀜";
            return null;
        });
    }

    static byte[] Half2(byte[] a, int len) { var h = new byte[len]; System.Array.Copy(a, h, len); return h; }
}

