using System;
using System.Text;

// FNV-1a 32비트 (RFC 9923). 빠른 비암호 해시: 해시 테이블 키, 에셋 지문, 우발적 손상 감지용.
public static class Fnv1a
{
    public const uint OffsetBasis32 = 2166136261u;   // 0x811C9DC5
    public const uint Prime32 = 16777619u;           // 0x01000193 = 2^24 + 2^8 + 0x93

    // 지금까지의 해시 hash 에 data 를 이어서 섞는다. 바이트마다 XOR 한 다음 곱한다(이 순서가 FNV-1a).
    public static uint Append(uint hash, ReadOnlySpan<byte> data)
    {
        foreach (byte b in data)
        {
            hash ^= b;
            hash = unchecked(hash * Prime32);   // 2^32 로 나눈 나머지. checked 빌드에서도 넘침 예외가 나지 않게 명시
        }
        return hash;
    }

    // 바이트 열 전체의 해시. 빈 입력이면 offset basis 그대로다.
    public static uint Hash32(ReadOnlySpan<byte> data) => Append(OffsetBasis32, data);

    // 문자열은 UTF-8 바이트로 바꿔서 해시한다(UTF-16 char 값을 그대로 섞지 않는다).
    public static uint Hash32Utf8(string text)
    {
        if (text == null) throw new ArgumentNullException(nameof(text));
        return Hash32(Encoding.UTF8.GetBytes(text));
    }
}

