using System;
using System.Collections.Generic;
using System.Threading.Tasks;

// 청크 하나를 만든 결과: 메시 정점 수와 충돌체 셀 수.
public readonly struct ChunkResult
{
    public ChunkResult(int vertices, int colliderCells) { Vertices = vertices; ColliderCells = colliderCells; }
    public int Vertices { get; }
    public int ColliderCells { get; }
}

// 오픈월드 청크 메시 서비스. Request 와 Tick 은 메인 루프(스레드 하나)에서만 불린다.
public sealed class ChunkMeshService
{
    private readonly Func<int[], int> _buildMesh;      // CPU 를 많이 쓴다(실제 게임에서 청크당 20~40ms)
    private readonly Func<int[], int> _buildCollider;  // CPU 를 많이 쓴다(청크당 5~10ms)
    private readonly List<(int chunkId, Task<ChunkResult> job)> _inFlight = new List<(int chunkId, Task<ChunkResult> job)>();
    private readonly Dictionary<int, ChunkResult> _applied = new Dictionary<int, ChunkResult>();

    public ChunkMeshService(Func<int[], int> buildMesh, Func<int[], int> buildCollider)
    {
        _buildMesh = buildMesh ?? throw new ArgumentNullException(nameof(buildMesh));
        _buildCollider = buildCollider ?? throw new ArgumentNullException(nameof(buildCollider));
    }

    // 렌더러가 메인 스레드에서 읽는 상태. Tick 안에서만 바뀐다.
    public IReadOnlyDictionary<int, ChunkResult> Applied => _applied;
    public int InFlightCount => _inFlight.Count;

    // 메인 루프가 부른다. 곧바로 돌아와야 한다.
    // 호출자는 이 메서드가 반환되자마자 voxels 배열을 다음 청크의 데이터로 다시 채운다.
    public void Request(int chunkId, int[] voxels)
    {
        _inFlight.Add((chunkId, BuildAsync(voxels)));
    }

    // 무거운 생성 작업을 비동기로 처리한다.
    private async Task<ChunkResult> BuildAsync(int[] voxels)
    {
        int colliderCells = _buildCollider(voxels);
        int vertices = await Task.Run(() => _buildMesh(voxels));
        return new ChunkResult(vertices, colliderCells);
    }

    // 메인 루프가 매 프레임 부른다. 끝난 작업의 결과만 Applied 에 반영하고,
    // 아직 끝나지 않은 작업은 다음 프레임으로 넘긴다. 프레임을 멈추게 하면 안 된다.
    public void Tick()
    {
        for (int i = _inFlight.Count - 1; i >= 0; i--)
        {
            var (chunkId, job) = _inFlight[i];
            _applied[chunkId] = job.Result;
            _inFlight.RemoveAt(i);
        }
    }
}

problems.solutionCode:
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

// 청크 하나를 만든 결과: 메시 정점 수와 충돌체 셀 수.
public readonly struct ChunkResult
{
    public ChunkResult(int vertices, int colliderCells) { Vertices = vertices; ColliderCells = colliderCells; }
    public int Vertices { get; }
    public int ColliderCells { get; }
}

// 오픈월드 청크 메시 서비스. Request 와 Tick 은 메인 루프(스레드 하나)에서만 불린다.
public sealed class ChunkMeshService
{
    private readonly Func<int[], int> _buildMesh;      // CPU 를 많이 쓴다(실제 게임에서 청크당 20~40ms)
    private readonly Func<int[], int> _buildCollider;  // CPU 를 많이 쓴다(청크당 5~10ms)
    // 아래 두 컬렉션은 메인 루프 스레드만 만진다. 워커는 자기 Task 의 결과만 만든다.
    private readonly List<(int chunkId, Task<ChunkResult> job)> _inFlight = new List<(int chunkId, Task<ChunkResult> job)>();
    private readonly Dictionary<int, ChunkResult> _applied = new Dictionary<int, ChunkResult>();

    public ChunkMeshService(Func<int[], int> buildMesh, Func<int[], int> buildCollider)
    {
        _buildMesh = buildMesh ?? throw new ArgumentNullException(nameof(buildMesh));
        _buildCollider = buildCollider ?? throw new ArgumentNullException(nameof(buildCollider));
    }

    // 렌더러가 메인 스레드에서 읽는 상태. Tick 안에서만 바뀐다.
    public IReadOnlyDictionary<int, ChunkResult> Applied => _applied;
    public int InFlightCount => _inFlight.Count;

    // 메인 루프가 부른다. 곧바로 돌아와야 한다.
    // 호출자는 이 메서드가 반환되자마자 voxels 배열을 다음 청크의 데이터로 다시 채운다.
    public void Request(int chunkId, int[] voxels)
    {
        if (voxels == null) throw new ArgumentNullException(nameof(voxels));
        // (버그 3) 호출자의 배열은 곧 덮어써지므로, 반환하기 전에 메인 스레드에서 이 작업 전용 복사본을 만든다.
        int[] snapshot = (int[])voxels.Clone();
        // (버그 1) async 라고 다른 스레드에서 도는 것이 아니다. CPU 작업은 전부 Task.Run 으로 스레드 풀에 보낸다.
        Task<ChunkResult> job = Task.Run(() => Build(snapshot));
        _inFlight.Add((chunkId, job));
    }

    // 워커 스레드에서 실행된다. 공유 상태를 건드리지 않고 결과만 돌려준다.
    private ChunkResult Build(int[] voxels)
    {
        int colliderCells = _buildCollider(voxels);
        int vertices = _buildMesh(voxels);
        return new ChunkResult(vertices, colliderCells);
    }

    // 메인 루프가 매 프레임 부른다. 끝난 작업의 결과만 Applied 에 반영하고,
    // 아직 끝나지 않은 작업은 다음 프레임으로 넘긴다. 프레임을 멈추게 하면 안 된다.
    public void Tick()
    {
        for (int i = _inFlight.Count - 1; i >= 0; i--)
        {
            var (chunkId, job) = _inFlight[i];
            // (버그 2) 끝나지 않은 작업의 Result 는 메인 스레드를 막는다. 끝난 것만 꺼낸다.
            if (!job.IsCompleted) continue;
            _applied[chunkId] = job.Result;   // 이미 끝났으므로 기다리지 않는다
            _inFlight.RemoveAt(i);
        }
    }
}

