public static class __Judge
{
    // 가짜 빌더. 문(gate)이 닫혀 있으면 열릴 때까지(최대 4초) 입력을 읽지 않고 기다린다 = "아직 계산 중".
    sealed class Rig
    {
        public readonly System.Threading.ManualResetEventSlim MeshGate = new System.Threading.ManualResetEventSlim(true);
        public readonly System.Threading.ManualResetEventSlim ColliderGate = new System.Threading.ManualResetEventSlim(true);
        public readonly System.Threading.ManualResetEventSlim SlowGate = new System.Threading.ManualResetEventSlim(true);
        public volatile int MainThreadId = -1;
        public volatile bool MeshOnMain, ColliderOnMain, GotCallerArray;
        public int MeshDone, ColliderDone;
        public int[] CallerBuffer;
        public int SlowMarker = int.MinValue;
        public int Mesh(int[] v)
        {
            if (System.Environment.CurrentManagedThreadId == MainThreadId) MeshOnMain = true;
            if (ReferenceEquals(v, CallerBuffer)) GotCallerArray = true;
            (v.Length > 0 && v[0] == SlowMarker ? SlowGate : MeshGate).Wait(4000);
            int r = MeshOf(v);
            System.Threading.Interlocked.Increment(ref MeshDone);
            return r;
        }
        public int Collider(int[] v)
        {
            if (System.Environment.CurrentManagedThreadId == MainThreadId) ColliderOnMain = true;
            if (ReferenceEquals(v, CallerBuffer)) GotCallerArray = true;
            ColliderGate.Wait(4000);
            int r = ColliderOf(v);
            System.Threading.Interlocked.Increment(ref ColliderDone);
            return r;
        }
        public void OpenAll() { MeshGate.Set(); ColliderGate.Set(); SlowGate.Set(); }
        public ChunkMeshService NewService() => new ChunkMeshService(Mesh, Collider);
    }

    static int MeshOf(int[] v) { int s = 0; for (int i = 0; i < v.Length; i++) s += v[i] * (i + 1); return s; }
    static int ColliderOf(int[] v) { int c = 0; foreach (int x in v) if (x > 0) c++; return c; }
    static int[] Data(int seed, int marker) { var r = new System.Random(seed); var a = new int[256]; for (int i = 0; i < a.Length; i++) a[i] = r.Next(-3, 10); a[0] = marker; return a; }
    static string Check(ChunkMeshService s, int id, int[] data)
    {
        if (!s.Applied.TryGetValue(id, out var got)) return "청크 " + id + " 의 결과가 Applied 에 없음";
        if (got.Vertices != MeshOf(data) || got.ColliderCells != ColliderOf(data))
            return "청크 " + id + ": 기대 (정점 " + MeshOf(data) + ", 충돌체 " + ColliderOf(data) + ") / 결과 (정점 " + got.Vertices + ", 충돌체 " + got.ColliderCells + ")";
        return null;
    }
    // 메인 루프처럼 1ms 마다 Tick 을 부르며 cond 가 참이 될 때까지 기다린다(최대 limitMs).
    static bool TickUntil(ChunkMeshService s, System.Func<bool> cond, int limitMs)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < limitMs) { s.Tick(); if (cond()) return true; System.Threading.Thread.Sleep(1); }
        return false;
    }

    // body 를 전용 "메인 루프" 스레드에서 실행한다. limitMs 안에 끝나지 않으면 메인 루프가 막힌 것으로 본다.
    static string OnMain(Rig rig, int limitMs, System.Func<string> body)
    {
        string result = null; System.Exception error = null;
        var t = new System.Threading.Thread(() => { rig.MainThreadId = System.Environment.CurrentManagedThreadId; try { result = body(); } catch (System.Exception e) { error = e; } });
        t.IsBackground = true;
        t.Start();
        if (!t.Join(limitMs)) { rig.OpenAll(); t.Join(3000); return "메인 루프가 " + limitMs + "ms 동안 돌아오지 않음(Request 나 Tick 이 작업이 끝나기를 기다리며 막힘)"; }
        if (error != null) return "예외 발생: " + error.GetType().Name + " " + error.Message;
        return result;
    }

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    public static void Main()
    {
        System.Threading.ThreadPool.SetMinThreads(4, 4);   // 막혀 있는 가짜 빌더(동시에 최대 2개) 때문에 풀 스레드 주입이 늦어지지 않게 한다. 채점 환경은 만들 수 있는 스레드 수가 적다
        var total = System.Diagnostics.Stopwatch.StartNew();

        Run("single-request-applied", () =>
        {
            var rig = new Rig();
            return OnMain(rig, 2000, () =>
            {
                var s = rig.NewService(); var a = Data(1, 7);
                s.Request(7, a);
                if (!TickUntil(s, () => s.Applied.ContainsKey(7), 1500)) return "1.5초 동안 Tick 을 불러도 청크 7 이 반영되지 않음";
                if (s.InFlightCount != 0) return "반영된 뒤에도 InFlightCount 가 " + s.InFlightCount;
                return Check(s, 7, a);
            });
        });

        Run("request-returns-immediately", () =>
        {
            var rig = new Rig(); rig.MeshGate.Reset(); rig.ColliderGate.Reset();
            return OnMain(rig, 1000, () =>
            {
                var s = rig.NewService(); var a = Data(2, 1);
                s.Request(1, a);   // 빌더는 문이 열릴 때까지 끝나지 않는다. Request 는 그래도 돌아와야 한다
                if (s.InFlightCount != 1 || s.Applied.Count != 0) return "Request 직후 InFlightCount=" + s.InFlightCount + ", Applied=" + s.Applied.Count + " (기대 1, 0)";
                rig.OpenAll();
                if (!TickUntil(s, () => s.Applied.ContainsKey(1), 800)) return "문을 연 뒤에도 청크 1 이 반영되지 않음";
                return Check(s, 1, a);
            });
        });

        Run("heavy-work-off-main-thread", () =>
        {
            var rig = new Rig();
            string e = OnMain(rig, 2000, () =>
            {
                var s = rig.NewService(); var d = new[] { Data(3, 1), Data(4, 2), Data(5, 3) };
                for (int i = 0; i < 3; i++) s.Request(100 + i, d[i]);
                if (!TickUntil(s, () => s.Applied.Count == 3, 1500)) return "청크 3개가 1.5초 안에 모두 반영되지 않음";
                for (int i = 0; i < 3; i++) { string c = Check(s, 100 + i, d[i]); if (c != null) return c; }
                return null;
            });
            if (e != null) return e;
            if (rig.ColliderOnMain) return "충돌체 생성(_buildCollider)이 메인 루프 스레드에서 실행됨";
            if (rig.MeshOnMain) return "메시 생성(_buildMesh)이 메인 루프 스레드에서 실행됨";
            return null;
        });

        Run("tick-never-waits", () =>
        {
            var rig = new Rig(); rig.MeshGate.Reset();
            return OnMain(rig, 1000, () =>
            {
                var s = rig.NewService(); var a = Data(6, 3);
                s.Request(3, a);
                s.Tick(); s.Tick();   // 메시가 아직 계산 중이다. Tick 은 기다리지 않고 돌아와야 한다
                if (s.Applied.ContainsKey(3) || s.InFlightCount != 1) return "끝나지 않은 작업이 Tick 에서 빠짐(Applied 에 있음=" + s.Applied.ContainsKey(3) + ", InFlightCount=" + s.InFlightCount + ")";
                rig.MeshGate.Set();
                if (!TickUntil(s, () => s.Applied.ContainsKey(3), 800)) return "문을 연 뒤에도 청크 3 이 반영되지 않음";
                return Check(s, 3, a);
            });
        });

        Run("caller-reuses-buffer", () =>
        {
            var rig = new Rig();   // 문은 열어 둔다: 채점 환경은 스레드 수가 적어 막힌 작업을 많이 만들지 않는다
            return OnMain(rig, 1500, () =>
            {
                var s = rig.NewService(); var data = new int[6][];
                for (int i = 0; i < 6; i++) data[i] = Data(7 + i, i + 1);
                var buf = new int[256]; rig.CallerBuffer = buf;
                for (int i = 0; i < 6; i++)
                {
                    System.Array.Copy(data[i], buf, buf.Length);   // 호출자가 같은 배열을 이번 청크 데이터로 채우고
                    s.Request(10 + i, buf);                        // 요청한 뒤 곧바로 다음 청크 데이터로 덮어쓴다
                }
                System.Array.Copy(Data(99, 9), buf, buf.Length);   // 다음 프레임 준비로 또 덮어쓴다
                if (!TickUntil(s, () => s.Applied.Count == 6, 1200)) return "청크 10~15 가 모두 반영되지 않음";
                for (int i = 0; i < 6; i++) { string e = Check(s, 10 + i, data[i]); if (e != null) return e + " (작업이 호출자가 다시 채운 배열을 읽음)"; }
                return rig.GotCallerArray ? "빌더가 호출자의 배열을 복사하지 않고 그대로 받음" : null;
            });
        });

        Run("tick-no-timed-waits", () =>
        {
            var rig = new Rig(); rig.MeshGate.Reset();
            return OnMain(rig, 2500, () =>
            {
                var s = rig.NewService(); var a = Data(13, 6);
                s.Request(40, a);
                var t = new double[21];   // 메시가 아직 계산 중인 작업 하나를 두고 Tick 21회의 시간을 잰다
                for (int r = 0; r < t.Length; r++) { var sw = System.Diagnostics.Stopwatch.StartNew(); s.Tick(); t[r] = sw.Elapsed.TotalMilliseconds; }
                System.Array.Sort(t);
                rig.MeshGate.Set();
                if (t[10] >= 0.5) return "끝나지 않은 작업 하나가 있을 때 Tick 시간의 중앙값이 " + t[10].ToString("F2") + "ms(21회). Wait(1) 처럼 잠깐씩이라도 기다리는 코드로 보임";
                if (!TickUntil(s, () => s.Applied.ContainsKey(40), 800)) return "문을 연 뒤에도 청크 40 이 반영되지 않음";
                return Check(s, 40, a);
            });
        });

        Run("partial-completion", () =>
        {
            var rig = new Rig(); rig.SlowMarker = 555; rig.SlowGate.Reset();
            return OnMain(rig, 1500, () =>
            {
                var s = rig.NewService(); var slow = Data(10, 555); var fast = Data(11, 4);
                s.Request(20, slow); s.Request(21, fast);
                if (!TickUntil(s, () => s.Applied.ContainsKey(21), 1000)) return "먼저 끝난 청크 21 이 반영되지 않음";
                if (s.Applied.ContainsKey(20) || s.InFlightCount != 1) return "아직 계산 중인 청크 20 이 Tick 에서 사라짐(InFlightCount=" + s.InFlightCount + ")";
                rig.SlowGate.Set();
                if (!TickUntil(s, () => s.Applied.ContainsKey(20), 800)) return "문을 연 뒤에도 청크 20 이 반영되지 않음";
                return Check(s, 20, slow) ?? Check(s, 21, fast);
            });
        });

        Run("applied-changes-only-in-tick", () =>
        {
            var rig = new Rig();
            return OnMain(rig, 2500, () =>
            {
                var s = rig.NewService(); var a = Data(12, 5);
                s.Request(30, a);
                var sw = System.Diagnostics.Stopwatch.StartNew();
                while ((System.Threading.Volatile.Read(ref rig.MeshDone) < 1 || System.Threading.Volatile.Read(ref rig.ColliderDone) < 1) && sw.ElapsedMilliseconds < 1500) System.Threading.Thread.Sleep(1);
                if (sw.ElapsedMilliseconds >= 1500) return "빌더가 1.5초 안에 끝나지 않음";
                var quiet = System.Diagnostics.Stopwatch.StartNew();   // 빌더가 끝난 뒤 300ms 동안 Tick 없이 지켜본다
                while (quiet.ElapsedMilliseconds < 300) { if (s.Applied.Count != 0) return "Tick 을 부르지 않았는데 Applied 가 바뀜(워커 스레드가 메인 스레드 상태를 직접 씀)"; System.Threading.Thread.Sleep(1); }
                if (!TickUntil(s, () => s.Applied.ContainsKey(30), 800)) return "Tick 을 불러도 청크 30 이 반영되지 않음";
                return Check(s, 30, a);
            });
        });

        if (total.ElapsedMilliseconds > 9000) System.Console.WriteLine("(채점 전체 " + total.ElapsedMilliseconds + "ms)");
    }
}

problems.scenario:
Windows PC 판과 리눅스 전용 서버 빌드를 함께 내는 2D 리듬 액션 게임입니다. 자체 C# 프레임 루프에 60fps 제한을 넣었습니다.

```csharp
while (running)
{
    long start = Stopwatch.GetTimestamp();
    Update(); Render();                                   // 보통 2~3ms
    int elapsedMs = (int)Stopwatch.GetElapsedTime(start).TotalMilliseconds;
    int wait = 16 - elapsedMs;
    if (wait > 0) Thread.Sleep(wait);                     // 남는 시간만큼 쉰다
}
```

QA 보고는 이렇습니다.

- Windows PC 에서 60fps 가 아니라 **약 32fps** 가 나온다. 리눅스 서버 빌드의 같은 루프는 초당 거의 60회 돈다.
- 애셋 로딩 스레드를 `ThreadPriority.Highest` 로 올리자 로딩은 빨라졌지만, 로딩 중에 입력과 음악 동기화가 끊긴다.
- 같은 팀의 Unity 6 모바일 버전은 60Hz 화면의 Android 기기에서 `Application.targetFrameRate = 25` 로 했더니 20fps 가 나오고, 데스크톱 빌드는 `QualitySettings.vSyncCount = 0; Application.targetFrameRate = 60;` 인데 미세하게 떨린다.

이 문제를 만들면서 같은 루프(일 2ms + `Thread.Sleep(16 - 경과)`)를 60프레임 돌려 보니, Windows 11 PC(.NET 8, 이 프로세스는 `timeBeginPeriod` 를 부르지 않음)에서는 프레임 간격 중앙값이 31.0ms, 채점 서버의 리눅스(.NET 8)에서는 16.1ms 였습니다(검수 때 다시 재도 각각 30.9~31.0ms, 16.1ms). PC 한 대와 채점 서버에서 잰 관찰값이지 보장된 수치가 아닙니다.

**질문: 운영 체제 스케줄러가 스레드에 CPU 를 나눠 주는 방식(타임 슬라이스, 우선순위, 선점)과 `Sleep` 의 정밀도가 무엇에 달려 있는지 설명하고, 위 세 증상이 각각 왜 생기는지 말해 주세요. 그리고 게임의 프레임 페이싱(고른 프레임 간격)을 어떻게 설계하겠습니까?**

