problems.solutionCode:
using System;

// 채팅·이모트 도배 방지용 토큰 버킷. 시간은 주입된 시계(단조 증가하는 ms)로만 읽는다.
public sealed class TokenBucket
{
    private readonly Func<long> _clockMs;
    private readonly long _intervalMs;
    private int _tokens;
    private long _origin;   // 아직 토큰으로 바꾸지 않은 시간이 시작된 시각

    // capacity: 버스트 용량(가득 찬 버킷의 토큰 수). refillIntervalMs: 토큰 1개가 차는 데 걸리는 시간.
    // 버킷은 가득 찬 상태로 시작한다.
    public TokenBucket(int capacity, long refillIntervalMs, Func<long> clockMs)
    {
        if (capacity < 1) throw new ArgumentOutOfRangeException(nameof(capacity));
        if (refillIntervalMs < 1) throw new ArgumentOutOfRangeException(nameof(refillIntervalMs));
        _clockMs = clockMs ?? throw new ArgumentNullException(nameof(clockMs));
        Capacity = capacity;
        _intervalMs = refillIntervalMs;
        _tokens = capacity;
        _origin = _clockMs();
    }

    public int Capacity { get; }

    // 지금 시각까지 채운 뒤의 토큰 수.
    public int Available
    {
        get { Refill(_clockMs()); return _tokens; }
    }

    // count 개를 한꺼번에 쓴다. 모자라면 하나도 쓰지 않고 false.
    public bool TryConsume(int count = 1)
    {
        ValidateCount(count);
        Refill(_clockMs());
        if (_tokens < count) return false;
        _tokens -= count;
        return true;
    }

    // count 개가 모일 때까지 남은 ms. 지금 쓸 수 있으면 0.
    public long MillisUntilAvailable(int count = 1)
    {
        ValidateCount(count);
        long now = _clockMs();
        Refill(now);
        if (_tokens >= count) return 0;
        long progress = Math.Max(0, now - _origin);          // 다음 토큰을 향해 이미 흐른 시간
        return (count - _tokens) * _intervalMs - progress;
    }

    private void ValidateCount(int count)
    {
        if (count < 1 || count > Capacity) throw new ArgumentOutOfRangeException(nameof(count));
    }

    private void Refill(long now)
    {
        long elapsed = now - _origin;
        if (elapsed <= 0) return;                            // 시간이 안 흘렀거나 시계가 뒤로 갔다: 아무것도 바꾸지 않는다
        long whole = elapsed / _intervalMs;                  // 다 찬 토큰만 더한다(내림)
        if (whole >= Capacity - _tokens)
        {
            _tokens = Capacity;                              // 넘치는 양과 자투리 시간은 버린다
            _origin = now;
            return;
        }
        _tokens += (int)whole;
        _origin += whole * _intervalMs;                      // 자투리 시간(elapsed % interval)은 다음 계산으로 넘긴다
    }
}

