{{USER_CODE}}

public static class __Judge
{
    static long now;   // 가짜 시계(ms)
    static TokenBucket New(int cap, long interval) => new TokenBucket(cap, interval, () => now);

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }
    static string Expect(string what, long expected, long actual) => expected == actual ? null : what + ": 기대 " + expected + " / 결과 " + actual;
    static bool Throws(System.Action a) { try { a(); return false; } catch (System.ArgumentOutOfRangeException) { return true; } }

    public static void Main()
    {
        Run("burst-capacity", () =>
        {
            now = 1000; var b = New(5, 1000);
            if (b.Capacity != 5 || b.Available != 5) return "새 버킷은 가득(5) 차 있어야 함: Available=" + b.Available;
            for (int i = 0; i < 5; i++) if (!b.TryConsume()) return "t=1000 에서 " + (i + 1) + "번째 소비가 거부됨(버스트 5 허용)";
            if (b.TryConsume()) return "t=1000 에서 6번째 소비가 허용됨(버스트 용량 초과)";
            return Expect("6번째 거부 뒤 Available", 0, b.Available);
        });

        Run("refill-keeps-remainder", () =>
        {
            now = 0; var b = New(5, 1000);
            b.TryConsume(5);
            now = 999; string e = Expect("t=999 Available", 0, b.Available); if (e != null) return e;
            now = 1500; e = Expect("t=1500 Available(1개 + 자투리 500ms)", 1, b.Available); if (e != null) return e;
            if (!b.TryConsume()) return "t=1500 에서 소비가 거부됨";
            now = 1999; e = Expect("t=1999 Available", 0, b.Available); if (e != null) return e;
            now = 2000; e = Expect("t=2000 Available(자투리 500ms 가 이어져야 함)", 1, b.Available); if (e != null) return e;
            now = 4600; return Expect("t=4600 Available", 3, b.Available);
        });

        Run("full-bucket-no-banking", () =>
        {
            now = 0; var b = New(3, 100);
            now = 10_050; string e = Expect("오래 쉰 뒤 Available(용량 3)", 3, b.Available); if (e != null) return e;
            if (!b.TryConsume()) return "t=10050 소비가 거부됨";
            now = 10_100; e = Expect("가득 찬 동안의 시간은 쌓이지 않음: t=10100 Available", 2, b.Available); if (e != null) return e;
            now = 10_149; e = Expect("t=10149 Available", 2, b.Available); if (e != null) return e;
            now = 10_150; return Expect("t=10150 Available(소비 후 정확히 100ms)", 3, b.Available);
        });

        Run("all-or-nothing", () =>
        {
            now = 0; var b = New(5, 1000);
            if (!b.TryConsume(3)) return "TryConsume(3) 이 거부됨";
            if (b.TryConsume(3)) return "토큰 2개뿐인데 TryConsume(3) 이 허용됨";
            string e = Expect("거부된 요청은 토큰을 쓰지 않음: Available", 2, b.Available); if (e != null) return e;
            if (!b.TryConsume(2)) return "TryConsume(2) 가 거부됨";
            return Expect("Available", 0, b.Available);
        });

        Run("argument-validation", () =>
        {
            now = 0; var b = New(4, 50);
            if (!Throws(() => b.TryConsume(0))) return "TryConsume(0) 이 ArgumentOutOfRangeException 을 던지지 않음";
            if (!Throws(() => b.TryConsume(5))) return "용량보다 큰 TryConsume(5) 가 ArgumentOutOfRangeException 을 던지지 않음";
            if (!Throws(() => b.MillisUntilAvailable(-1))) return "MillisUntilAvailable(-1) 이 ArgumentOutOfRangeException 을 던지지 않음";
            if (!Throws(() => new TokenBucket(0, 50, () => now))) return "용량 0 버킷 생성이 허용됨";
            if (!Throws(() => new TokenBucket(3, 0, () => now))) return "간격 0 버킷 생성이 허용됨";
            return Expect("잘못된 호출 뒤 Available", 4, b.Available);
        });

        Run("millis-until-available", () =>
        {
            now = 0; var b = New(5, 1000);
            string e = Expect("가득 찬 버킷의 MillisUntilAvailable(5)", 0, b.MillisUntilAvailable(5)); if (e != null) return e;
            b.TryConsume(5);
            now = 300;
            e = Expect("t=300 MillisUntilAvailable(1)", 700, b.MillisUntilAvailable(1)) ?? Expect("t=300 MillisUntilAvailable(3)", 2700, b.MillisUntilAvailable(3));
            if (e != null) return e;
            now = 3000;
            return Expect("t=3000 MillisUntilAvailable(3)", 0, b.MillisUntilAvailable(3)) ?? Expect("t=3000 MillisUntilAvailable(5)", 2000, b.MillisUntilAvailable(5));
        });

        Run("clock-backwards", () =>
        {
            now = 5000; var b = New(2, 1000);
            b.TryConsume(2);
            now = 4000;   // 시계가 뒤로 감
            string e = Expect("시계가 뒤로 간 뒤 Available", 0, b.Available); if (e != null) return e;
            if (b.TryConsume()) return "시계가 뒤로 간 뒤 토큰이 생김";
            now = 5999; e = Expect("t=5999 Available", 0, b.Available); if (e != null) return e;
            now = 6000; return Expect("원래 기준 시각에서 1000ms 뒤(t=6000) Available", 1, b.Available);
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(2026);
            long[] intervals = { 1, 3, 7, 100, 333, 1000 };
            for (int round = 0; round < 60; round++)
            {
                int cap = rng.Next(1, 9); long iv = intervals[rng.Next(intervals.Length)];
                now = rng.Next(0, 100000); var b = New(cap, iv);
                long level = cap * iv, last = now;   // 참조 모델: 'ms 단위 크레딧'이 연속으로 차오르고 cap*iv 에서 넘친다
                for (int step = 0; step < 300; step++)
                {
                    int k = rng.Next(100);
                    now += k < 30 ? 0 : k < 70 ? rng.Next(1, (int)iv * 2 + 2) : k < 95 ? rng.Next(1, 7) : rng.Next(1, 50000);
                    level = System.Math.Min(cap * iv, level + (now - last)); last = now;
                    int n = rng.Next(1, cap + 1); int op = rng.Next(3);
                    string where = "용량 " + cap + ", 간격 " + iv + "ms, " + step + "번째 호출(t=" + now + ")";
                    if (op == 0)
                    {
                        bool exp = level >= n * iv; if (exp) level -= n * iv;
                        bool got = b.TryConsume(n);
                        if (got != exp) return where + ": TryConsume(" + n + ") 기대 " + exp + " / 결과 " + got;
                    }
                    else if (op == 1) { string e = Expect(where + ": Available", level / iv, b.Available); if (e != null) return e; }
                    else { string e = Expect(where + ": MillisUntilAvailable(" + n + ")", System.Math.Max(0, n * iv - level), b.MillisUntilAvailable(n)); if (e != null) return e; }
                }
            }
            return null;
        });
    }
}

problems.starterCode:
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

public enum TokenKind { Word, String, Integer, Float }

// 토큰 하나.
// Text  : Word 는 원문 그대로, String 은 따옴표를 벗기고 이스케이프를 푼 내용, Integer / Float 는 원문 그대로.
// Start : 원문에서 토큰이 시작하는 위치(String 은 여는 따옴표의 위치).
// IntValue 는 Kind == Integer 일 때만, FloatValue 는 Kind == Float 일 때만 의미가 있고 그 밖에는 0 이다.
public readonly record struct Token(TokenKind Kind, string Text, int Start, int IntValue, double FloatValue);

public sealed class TokenizeResult
{
    public List<Token> Tokens { get; } = new List<Token>();
    public int ErrorIndex { get; private set; } = -1;   // 오류가 없으면 -1
    public string ErrorMessage { get; private set; } = "";
    public bool Ok => ErrorIndex < 0;

