using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

public enum TokenKind { Word, String, Integer, Float }

// 토큰 하나.
// Text  : Word 는 원문 그대로, String 은 따옴표를 벗기고 이스케이프를 푼 내용, Integer / Float 는 원문 그대로.
// Start : 원문에서 토큰이 시작하는 위치(String 은 여는 따옴표의 위치).
// IntValue 는 Kind == Integer 일 때만, FloatValue 는 Kind == Float 일 때만 의미가 있고 그 밖에는 0 이다.
public readonly record struct Token(TokenKind Kind, string Text, int Start, int IntValue, double FloatValue);

public sealed class TokenizeResult
{
    public List<Token> Tokens { get; } = new List<Token>();
    public int ErrorIndex { get; private set; } = -1;   // 오류가 없으면 -1
    public string ErrorMessage { get; private set; } = "";
    public bool Ok => ErrorIndex < 0;

    // 오류를 기록한다. 오류가 나면 그때까지 만든 토큰은 버린다.
    public TokenizeResult Fail(int index, string message)
    {
        Tokens.Clear();
        ErrorIndex = index;
        ErrorMessage = message;
        return this;
    }
}

public static class ConsoleTokenizer
{
    public static TokenizeResult Tokenize(string line)
    {
        if (line == null) throw new ArgumentNullException(nameof(line));

        var result = new TokenizeResult();
        var sb = new StringBuilder();
        int i = 0, n = line.Length;

        while (true)
        {
            while (i < n && IsSeparator(line[i])) i++;      // 토큰 사이의 구분자를 건너뛴다
            if (i >= n) return result;

            int start = i;
            if (line[i] == '"')
            {
                // 따옴표 문자열: 닫는 따옴표까지 읽으며 이스케이프를 푼다.
                sb.Clear();
                i++;
                bool closed = false;
                while (i < n)
                {
                    char c = line[i];
                    if (c == '"') { closed = true; i++; break; }
                    if (c == '\\')
                    {
                        if (i + 1 >= n) break;                // 이스케이프 도중 줄이 끝남 = 닫히지 않은 문자열
                        switch (line[i + 1])
                        {
                            case '"': sb.Append('"'); break;
                            case '\\': sb.Append('\\'); break;
                            case 'n': sb.Append('\n'); break;
                            case 't': sb.Append('\t'); break;
                            default: return result.Fail(i, "알 수 없는 이스케이프");
                        }
                        i += 2;
                        continue;
                    }
                    sb.Append(c);
                    i++;
                }
                if (!closed) return result.Fail(start, "닫히지 않은 따옴표");
                if (i < n && !IsSeparator(line[i])) return result.Fail(i, "닫는 따옴표 바로 뒤에 다른 문자가 있음");
                result.Tokens.Add(new Token(TokenKind.String, sb.ToString(), start, 0, 0));
                continue;
            }

            // 따옴표 없는 토큰: 다음 구분자까지. 중간에 따옴표가 있으면 오류.
            while (i < n && !IsSeparator(line[i]))
            {
                if (line[i] == '"') return result.Fail(i, "따옴표 없는 토큰 중간에 따옴표가 있음");
                i++;
            }
            string text = line.Substring(start, i - start);

            switch (Classify(text))
            {
                case TokenKind.Integer:
                    // 문법은 이미 확인했으므로 실패 원인은 범위 초과뿐이다. 문화권과 무관하게 해석한다.
                    if (!int.TryParse(text, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out int value))
                        return result.Fail(start, "정수 범위를 벗어남");
                    result.Tokens.Add(new Token(TokenKind.Integer, text, start, value, 0));
                    break;
                case TokenKind.Float:
                    double d = double.Parse(text, NumberStyles.AllowLeadingSign | NumberStyles.AllowDecimalPoint, CultureInfo.InvariantCulture);
                    result.Tokens.Add(new Token(TokenKind.Float, text, start, 0, d));
                    break;
                default:
                    result.Tokens.Add(new Token(TokenKind.Word, text, start, 0, 0));
                    break;
            }
        }
    }

    private static bool IsSeparator(char c) => c == ' ' || c == '\t';

    // 숫자 문법: [+|-] 숫자+            → Integer
    //            [+|-] 숫자+ '.' 숫자+  → Float
    // 숫자는 ASCII '0'~'9' 만 인정한다(char.IsDigit 은 전각 숫자 등 다른 문자의 숫자도 true).
    private static TokenKind Classify(string s)
    {
        int k = 0;
        if (s[0] == '+' || s[0] == '-') k++;
        int intDigits = 0;
        while (k < s.Length && char.IsAsciiDigit(s[k])) { k++; intDigits++; }
        if (intDigits == 0) return TokenKind.Word;
        if (k == s.Length) return TokenKind.Integer;
        if (s[k] != '.') return TokenKind.Word;
        k++;
        int fracDigits = 0;
        while (k < s.Length && char.IsAsciiDigit(s[k])) { k++; fracDigits++; }
        return fracDigits > 0 && k == s.Length ? TokenKind.Float : TokenKind.Word;
    }
}

