public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Show(string s)
    {
        string t = s.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\n", "\\n").Replace("\t", "\\t");
        return "\"" + (t.Length > 70 ? t.Substring(0, 70) + "…" : t) + "\"";
    }

    static string Describe(Token t)
    {
        string v = t.Kind == TokenKind.Integer ? "=" + t.IntValue
                 : t.Kind == TokenKind.Float ? "=" + t.FloatValue.ToString("R", System.Globalization.CultureInfo.InvariantCulture) : "";
        return t.Kind + " " + Show(t.Text ?? "(null)") + " @" + t.Start + v;
    }

    static bool Same(Token g, Token w)
    {
        if (g.Kind != w.Kind || g.Text != w.Text || g.Start != w.Start || g.IntValue != w.IntValue) return false;
        if (w.Kind != TokenKind.Float) return g.FloatValue == 0;
        return System.Math.Abs(g.FloatValue - w.FloatValue) <= 1e-12 * System.Math.Max(1.0, System.Math.Abs(w.FloatValue));
    }

    static string Expect(string line, System.Collections.Generic.List<Token> want)
    {
        var r = ConsoleTokenizer.Tokenize(line);
        if (r == null) return "Tokenize(" + Show(line) + ") 가 null 을 반환";
        if (!r.Ok) return "Tokenize(" + Show(line) + ") 기대: 성공 / 결과: 위치 " + r.ErrorIndex + " 오류(" + r.ErrorMessage + ")";
        if (r.Tokens.Count != want.Count) return "Tokenize(" + Show(line) + ") 토큰 수 기대 " + want.Count + " / 결과 " + r.Tokens.Count;
        for (int k = 0; k < want.Count; k++)
            if (!Same(r.Tokens[k], want[k])) return "Tokenize(" + Show(line) + ") " + k + "번째 토큰 기대 " + Describe(want[k]) + " / 결과 " + Describe(r.Tokens[k]);
        return null;
    }

    static string Expect(string line, params Token[] want) => Expect(line, new System.Collections.Generic.List<Token>(want));

    static string ExpectError(string line, int index)
    {
        var r = ConsoleTokenizer.Tokenize(line);
        if (r.Ok) return "Tokenize(" + Show(line) + ") 기대: 위치 " + index + " 오류 / 결과: 성공(토큰 " + r.Tokens.Count + "개)";
        if (r.ErrorIndex != index) return "Tokenize(" + Show(line) + ") 오류 위치 기대 " + index + " / 결과 " + r.ErrorIndex;
        if (r.Tokens.Count != 0) return "Tokenize(" + Show(line) + ") 오류인데 Tokens 가 비어 있지 않음(" + r.Tokens.Count + "개)";
        if (string.IsNullOrEmpty(r.ErrorMessage)) return "Tokenize(" + Show(line) + ") 오류 메시지가 비어 있음";
        return null;
    }

    static Token W(string t, int s) => new Token(TokenKind.Word, t, s, 0, 0);
    static Token S(string t, int s) => new Token(TokenKind.String, t, s, 0, 0);
    static Token I(string t, int s, int v) => new Token(TokenKind.Integer, t, s, v, 0);
    static Token F(string t, int s, double v) => new Token(TokenKind.Float, t, s, 0, v);

    // 단어들을 공백 하나로 이어 한 줄을 만들고, 모두 Word 로 나와야 한다고 검사한다.
    static string AllWords(params string[] words)
    {
        var want = new System.Collections.Generic.List<Token>();
        int pos = 0;
        foreach (var w in words) { want.Add(W(w, pos)); pos += w.Length + 1; }
        return Expect(string.Join(" ", words), want);
    }

    public static void Main()
    {
        Run("words-and-separators", () =>
            Expect("  spawn   goblin\t3 ", W("spawn", 2), W("goblin", 10), I("3", 17, 3))
            ?? Expect("") ?? Expect(" \t  ")
            ?? Expect("load C:\\maps\\a.map --elite", W("load", 0), W("C:\\maps\\a.map", 5), W("--elite", 19)));

        Run("quoted-strings-and-escapes", () =>
            Expect("say \"Goblin King\" \"\"", W("say", 0), S("Goblin King", 4), S("", 18))
            ?? Expect("\"42\"", S("42", 0))
            ?? Expect("say \"He said \\\"hi\\\"\"", W("say", 0), S("He said \"hi\"", 4))
            ?? Expect("\"C:\\\\temp\" \"a\\nb\\tc\"", S("C:\\temp", 0), S("a\nb\tc", 11))
            ?? Expect("tp \"x y\"\t\"z\"", W("tp", 0), S("x y", 3), S("z", 9)));

        Run("numbers-culture-independent", () =>
        {
            string e = Expect("3 -12 +7 007 -0 0.25 -0.5 +2.75 3.14159265358979",
                I("3", 0, 3), I("-12", 2, -12), I("+7", 6, 7), I("007", 9, 7), I("-0", 13, 0),
                F("0.25", 16, 0.25), F("-0.5", 21, -0.5), F("+2.75", 26, 2.75), F("3.14159265358979", 32, 3.14159265358979));
            if (e != null) return e;
            // 소수점이 ',' 이고 천 단위 구분자가 '.' 인 문화권의 PC 를 흉내 낸다.
            var saved = System.Globalization.CultureInfo.CurrentCulture;
            var comma = (System.Globalization.CultureInfo)System.Globalization.CultureInfo.InvariantCulture.Clone();
            comma.NumberFormat.NumberDecimalSeparator = ",";
            comma.NumberFormat.NumberGroupSeparator = ".";
            try
            {
                System.Globalization.CultureInfo.CurrentCulture = comma;
                e = Expect("speed 1.5 1,5 -2.25 1.000", W("speed", 0), F("1.5", 6, 1.5), W("1,5", 10), F("-2.25", 14, -2.25), F("1.000", 20, 1.0));
                return e == null ? null : "현재 문화권의 소수점이 ',' 일 때: " + e;
            }
            finally { System.Globalization.CultureInfo.CurrentCulture = saved; }
        });

        Run("number-like-words", () =>
            AllWords("-", "+", ".5", "5.", "1e3", "1.2.3", "0x1F", "1,000", "NaN", "Infinity", "12abc", "-x", "+-1", "3.", "-.5", "\uFF19\uFF19", "\u0663"));

        Run("int-range", () =>
            Expect("-2147483648 2147483647 0", I("-2147483648", 0, int.MinValue), I("2147483647", 12, int.MaxValue), I("0", 23, 0))
            ?? ExpectError("give 2147483648", 5) ?? ExpectError("x -2147483649 y", 2)
            ?? ExpectError("99999999999999999999", 0) ?? ExpectError("set +2147483648", 4));

        Run("errors", () =>
        {
            string e = ExpectError("say \"hello", 4) ?? ExpectError("say \"a\\qb\"", 6) ?? ExpectError("say ab\"c\"", 6)
                ?? ExpectError("say \"ab\"c", 8) ?? ExpectError("say \"abc\\", 4) ?? ExpectError("ok \"x\" \"\\r\"", 8);
            if (e != null) return e;
            try { ConsoleTokenizer.Tokenize(null); return "Tokenize(null) 이 ArgumentNullException 을 던지지 않음"; }
            catch (System.ArgumentNullException) { return null; }
        });

        Run("random-roundtrip", () =>
        {
            var rng = new System.Random(7401);
            const string wordChars = "abcxyz_-:/\\.,=09";
            const string strChars = "ab \"\\\n\t9.-한";
            for (int iter = 0; iter < 2000; iter++)
            {
                var sb = new System.Text.StringBuilder();
                var want = new System.Collections.Generic.List<Token>();
                int count = rng.Next(0, 7);
                for (int k = 0; k < count; k++)
                {
                    int gap = rng.Next(k == 0 ? 0 : 1, 4);
                    for (int g = 0; g < gap; g++) sb.Append(rng.Next(2) == 0 ? ' ' : '\t');
                    int start = sb.Length, kind = rng.Next(4);
                    if (kind == 0)
                    {
                        string w = "k" + RandomText(rng, wordChars, rng.Next(0, 6));
                        sb.Append(w); want.Add(W(w, start));
                    }
                    else if (kind == 1)
                    {
                        string raw = RandomText(rng, strChars, rng.Next(0, 8));
                        sb.Append('"').Append(raw.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\n", "\\n").Replace("\t", "\\t")).Append('"');
                        want.Add(S(raw, start));
                    }
                    else if (kind == 2)
                    {
                        int v = rng.Next(int.MinValue, int.MaxValue);
                        string t = (v >= 0 && rng.Next(3) == 0 ? "+" : "") + v.ToString(System.Globalization.CultureInfo.InvariantCulture);
                        sb.Append(t); want.Add(I(t, start, v));
                    }
                    else
                    {
                        string t = (rng.Next(3) == 0 ? "-" : "") + rng.Next(0, 100000) + "." + RandomText(rng, "0123456789", rng.Next(1, 7));
                        sb.Append(t); want.Add(F(t, start, double.Parse(t, System.Globalization.CultureInfo.InvariantCulture)));
                    }
                }
                if (rng.Next(2) == 0) sb.Append(' ');
                string e = Expect(sb.ToString(), want);
                if (e != null) return "무작위 " + iter + "번째: " + e;
            }
            return null;
        });

        Run("long-line-linear", () =>
        {
            ConsoleTokenizer.Tokenize("warm \"up\" 1 2.5");
            var sb = new System.Text.StringBuilder("say \"");
            for (int k = 0; k < 30000; k++) sb.Append("ab\\\"c ");
            sb.Append('"');
            for (int k = 0; k < 30000; k++) sb.Append(" w").Append(k % 10);
            string line = sb.ToString();
            var watch = System.Diagnostics.Stopwatch.StartNew();
            var r = ConsoleTokenizer.Tokenize(line);
            long ms = watch.ElapsedMilliseconds;
            if (!r.Ok || r.Tokens.Count != 30002) return "길이 " + line.Length + " 줄: 기대 토큰 30002개 / 결과 " + (r.Ok ? r.Tokens.Count + "개" : "오류 " + r.ErrorIndex);
            if (r.Tokens[1].Kind != TokenKind.String || r.Tokens[1].Text.Length != 150000) return "긴 따옴표 문자열의 내용 길이 기대 150000 / 결과 " + r.Tokens[1].Text.Length;
            if (r.Tokens[30001].Start != line.Length - 2) return "마지막 토큰 위치 기대 " + (line.Length - 2) + " / 결과 " + r.Tokens[30001].Start;
            return ms <= 500 ? null : "길이 " + line.Length + " 줄 처리에 " + ms + " ms (기대: 500 ms 이내, 한 번 훑는 O(n) 이면 수 ms)";
        });
    }

    static string RandomText(System.Random rng, string alphabet, int len)
    {
        var c = new char[len];
        for (int k = 0; k < len; k++) c[k] = alphabet[rng.Next(alphabet.Length)];
        return new string(c);
    }
}

problems.starterCode:
using System;
using System.Collections.Generic;

// 게임 코드가 시간을 읽는 유일한 통로. 실제 게임은 Stopwatch 와 기기 시계를 감싼 구현을, 테스트는 가짜 시계를 넣는다.
public interface IGameClock
{
    // 단조 시계: 앱이 시작된 뒤 흐른 실제 시간. 절대 뒤로 가지 않으며 기기 시각 변경, NTP 의 시각 점프,
    // 시간대·일광 절약 시간의 영향을 받지 않는다(Stopwatch 와 같은 성질). 앱을 다시 켜면 0 부터 다시 센다.
    TimeSpan Monotonic { get; }

    // 벽시계: 기기 시계가 말하는 현재 UTC 시각(Kind = Utc). 시간대·일광 절약 시간과는 무관하지만,
    // 사용자가 기기 시각을 바꾸거나 NTP 가 보정하면 앞뒤로 점프할 수 있다.
    DateTime UtcNow { get; }
}

// 스킬 쿨다운. 앱이 켜져 있는 동안의 쿨다운만 다룬다(재시작 후에도 이어지는 타이머는 서버가 관리한다).
public sealed class SkillCooldowns
{
    private readonly IGameClock _clock;
    private readonly Dictionary<int, DateTime> _readyAt = new Dictionary<int, DateTime>();

    public SkillCooldowns(IGameClock clock) { _clock = clock; }

    // skillId 의 쿨다운을 지금부터 seconds 초로 (다시) 시작한다.
    public void Start(int skillId, double seconds)
    {
        _readyAt[skillId] = _clock.UtcNow.AddSeconds(seconds);
    }

    // 남은 시간(초). 쿨다운을 시작한 적이 없거나 끝났으면 0.
    public double RemainingSeconds(int skillId)
    {
        if (!_readyAt.TryGetValue(skillId, out DateTime readyAt)) return 0;
        double left = (readyAt - _clock.UtcNow).TotalSeconds;
        return left > 0 ? left : 0;
    }

    public bool IsReady(int skillId) => RemainingSeconds(skillId) <= 0;
}

// 일일 보상 리셋: resetZone 의 현지 시각으로 매일 resetHour 시 정각에 "게임 날짜"가 바뀐다.
// resetZone 은 일광 절약 시간 규칙을 가질 수 있으며, 플레이어 기기의 시간대와는 무관하다.
// resetHour 는 그 시간대에서 건너뛰거나 두 번 오는 시각이 아니라고 가정한다.
public sealed class DailyReset
{
    private readonly TimeZoneInfo _resetZone;
    private readonly int _resetHour;

    public DailyReset(TimeZoneInfo resetZone, int resetHour)
    {
        _resetZone = resetZone;
        _resetHour = resetHour;
    }

    // utc(Kind = Utc) 가 속한 게임 날짜: 리셋 시간대의 현지 시각에서 resetHour 시간을 뺀 날짜.
    public DateTime GameDay(DateTime utc)
    {
        DateTime local = utc.ToLocalTime();
        return local.AddHours(-_resetHour).Date;
    }

    // 마지막으로 받은 뒤 리셋이 한 번이라도 지났으면 true.
    public bool CanClaim(DateTime lastClaimUtc, DateTime nowUtc) => GameDay(nowUtc) > GameDay(lastClaimUtc);

    // nowUtc 보다 늦은 첫 리셋 시각(UTC, Kind = Utc).
    public DateTime NextResetUtc(DateTime nowUtc)
    {
        DateTime local = nowUtc.ToLocalTime();
        DateTime next = local.Date.AddHours(_resetHour);
        if (next <= local) next = next.AddDays(1);
        return next.ToUniversalTime();
    }
}

// 보스 레이드 제한 시간. 게임 루프가 매 프레임 그 프레임의 deltaTime(초)을 넘긴다.
// 일시 정지 중에는 0, 슬로 모션 중에는 줄어든 값이 들어온다(그래서 시계를 읽지 않고 누적한다).
public sealed class RaidTimer
{
    private readonly float _limitSeconds;
    private float _elapsedSeconds;

    public RaidTimer(float limitSeconds) { _limitSeconds = limitSeconds; }

    public void Tick(float deltaSeconds) { _elapsedSeconds += deltaSeconds; }

    public bool IsOver => _elapsedSeconds >= _limitSeconds;

    // HUD 에 표시할 남은 시간(초).
    public float RemainingSeconds => Math.Max(0f, _limitSeconds - _elapsedSeconds);
}

