public static class __Judge
{
    sealed class FakeClock : IGameClock
    {
        public System.TimeSpan Monotonic { get; set; }
        public System.DateTime UtcNow { get; set; }
        // 실제 시간이 흐름: 두 시계가 함께 간다.
        public void Advance(double seconds) { Monotonic += System.TimeSpan.FromSeconds(seconds); UtcNow = UtcNow.AddSeconds(seconds); }
    }

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.DateTime U(int y, int mo, int d, int h, int mi = 0, int s = 0) => new System.DateTime(y, mo, d, h, mi, s, System.DateTimeKind.Utc);
    static string Iso(System.DateTime t) => t.ToString("yyyy-MM-dd HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture);

    static string Left(SkillCooldowns cd, int id, double want, bool ready, string when)
    {
        double got = cd.RemainingSeconds(id);
        if (System.Math.Abs(got - want) > 1e-4) return when + ": RemainingSeconds(" + id + ") 기대 " + want + " / 결과 " + got;
        if (cd.IsReady(id) != ready) return when + ": IsReady(" + id + ") 기대 " + ready + " / 결과 " + !ready;
        return null;
    }

    static string Day(DailyReset r, System.DateTime utc, int y, int mo, int d, string zone)
    {
        System.DateTime got = r.GameDay(utc);
        var want = new System.DateTime(y, mo, d);
        return got.Date == want && got.TimeOfDay == System.TimeSpan.Zero ? null
            : zone + ": GameDay(" + Iso(utc) + "Z) 기대 " + want.ToString("yyyy-MM-dd") + " / 결과 " + Iso(got);
    }

    static string Next(DailyReset r, System.DateTime utc, System.DateTime want, string zone)
    {
        System.DateTime got = r.NextResetUtc(utc);
        if (got != want) return zone + ": NextResetUtc(" + Iso(utc) + "Z) 기대 " + Iso(want) + "Z / 결과 " + Iso(got);
        return got.Kind == System.DateTimeKind.Utc ? null : zone + ": NextResetUtc 결과의 Kind 기대 Utc / 결과 " + got.Kind;
    }

    static string Claim(DailyReset r, System.DateTime last, System.DateTime now, bool want, string zone)
    {
        bool got = r.CanClaim(last, now);
        return got == want ? null : zone + ": CanClaim(" + Iso(last) + "Z, " + Iso(now) + "Z) 기대 " + want + " / 결과 " + got;
    }

    static System.TimeZoneInfo Kst() =>
        System.TimeZoneInfo.CreateCustomTimeZone("Judge/KST", System.TimeSpan.FromHours(9), "(UTC+09:00) KST", "KST");

    // EU 식 규칙: 3월 마지막 일요일 01:00 UTC 부터 10월 마지막 일요일 01:00 UTC 까지 UTC+2, 나머지는 UTC+1.
    static System.TimeZoneInfo EuLike()
    {
        var start = System.TimeZoneInfo.TransitionTime.CreateFloatingDateRule(new System.DateTime(1, 1, 1, 2, 0, 0), 3, 5, System.DayOfWeek.Sunday);
        var end = System.TimeZoneInfo.TransitionTime.CreateFloatingDateRule(new System.DateTime(1, 1, 1, 3, 0, 0), 10, 5, System.DayOfWeek.Sunday);
        var rule = System.TimeZoneInfo.AdjustmentRule.CreateAdjustmentRule(new System.DateTime(2000, 1, 1), new System.DateTime(2099, 12, 31), System.TimeSpan.FromHours(1), start, end);
        return System.TimeZoneInfo.CreateCustomTimeZone("Judge/EU", System.TimeSpan.FromHours(1), "(UTC+01:00) EU-like", "EU Standard", "EU Summer", new[] { rule });
    }

    // 프레임마다 dt 를 넣으며 IsOver 가 처음 true 가 되는 프레임을, 오차 없는 합(double)이 limit 에 닿는 프레임과 비교한다.
    static string RaidRun(float limit, System.Func<long, float> dtOf, string what)
    {
        var t = new RaidTimer(limit);
        double exact = 0; long refFrame = -1, gotFrame = -1;
        string remainErr = null;
        for (long f = 1; f <= 2_000_000 && (refFrame < 0 || gotFrame < 0); f++)
        {
            float dt = dtOf(f);
            t.Tick(dt); exact += dt;
            if (refFrame < 0 && exact >= limit) refFrame = f;
            if (gotFrame < 0 && t.IsOver) gotFrame = f;
            if (remainErr == null && f % 9973 == 0 && refFrame < 0 && System.Math.Abs(t.RemainingSeconds - (limit - exact)) > 0.01)
                remainErr = what + ": " + f + "번째 프레임의 RemainingSeconds 기대 " + (limit - exact).ToString("F4") + " / 결과 " + t.RemainingSeconds.ToString("F4");
        }
        if (System.Math.Abs(gotFrame - refFrame) > 3)
            return what + ": IsOver 가 처음 true 가 된 프레임 기대 " + refFrame + " ±3 / 결과 " + gotFrame + " (" + (gotFrame - refFrame) + "프레임 차이)";
        if (remainErr != null) return remainErr;
        if (t.RemainingSeconds != 0f) return what + ": 끝난 뒤 RemainingSeconds 기대 0 / 결과 " + t.RemainingSeconds;
        return null;
    }

    public static void Main()
