        {
            var c = new FakeClock { Monotonic = System.TimeSpan.FromSeconds(100), UtcNow = U(2026, 11, 22, 12) };
            var cd = new SkillCooldowns(c);
            string e = Left(cd, 7, 0, true, "시작한 적 없는 스킬");
            if (e != null) return e;
            cd.Start(7, 30);
            e = Left(cd, 7, 30, false, "Start(7, 30) 직후");
            c.Advance(10); e = e ?? Left(cd, 7, 20, false, "10초 뒤");
            c.Advance(19.5); e = e ?? Left(cd, 7, 0.5, false, "29.5초 뒤");
            c.Advance(0.5); e = e ?? Left(cd, 7, 0, true, "30초 뒤");
            if (e != null) return e;
            cd.Start(7, 2.5); cd.Start(8, 5);
            c.Advance(3);
            return Left(cd, 7, 0, true, "다시 시작한 2.5초 쿨다운의 3초 뒤") ?? Left(cd, 8, 2, false, "5초 쿨다운의 3초 뒤");
        });

