            c.UtcNow = c.UtcNow.AddHours(-2); c.Monotonic += System.TimeSpan.FromSeconds(1);
            e = Left(cd, 1, 28, false, "다시 1초 뒤 기기 시각을 2시간 뒤로 돌렸을 때");
            if (e != null) return e;
            c.UtcNow = c.UtcNow.AddSeconds(-0.5); c.Monotonic += System.TimeSpan.FromSeconds(1);
            e = Left(cd, 1, 27, false, "다시 1초 뒤 NTP 가 벽시계를 0.5초 늦췄을 때");
