using System;

// 기본형(blittable) 필드만 가진 struct 의 크기를 문서의 정렬 규칙으로 계산한다.
// 측정 API(sizeof, Unsafe.SizeOf, Marshal.SizeOf)는 쓰지 않는다.
public static class LayoutMath
{
    // fieldSizes: 선언 순서대로 각 필드의 크기(1, 2, 4, 8 중 하나, 1개 이상).
    // 반환: struct 한 개의 크기(바이트). 필드 사이 패딩과 끝 패딩을 포함한다.
    public static int SequentialSize(int[] fieldSizes)
    {
        int offset = 0;
        int typeAlignment = 1;
        foreach (int size in fieldSizes)
        {
            int alignment = size;                 // 필드는 자기 크기의 경계에 놓인다(8바이트 이하 필드)
            offset = AlignUp(offset, alignment);  // 필드 앞 패딩
            offset += size;
            if (alignment > typeAlignment) typeAlignment = alignment;   // 타입의 정렬 = 가장 큰 필드
        }
        // 끝 패딩: 배열의 다음 요소도 같은 규칙을 지키려면 크기가 타입 정렬의 배수여야 한다.
        return AlignUp(offset, typeAlignment);
    }

    // 같은 필드들을 패딩이 가장 적게 생기는 순서(큰 필드부터)로 선언했을 때의 크기.
    public static int SmallestSize(int[] fieldSizes)
    {
        int[] sorted = (int[])fieldSizes.Clone();
        Array.Sort(sorted);
        Array.Reverse(sorted);
        return SequentialSize(sorted);
    }

    private static int AlignUp(int value, int alignment) => (value + alignment - 1) / alignment * alignment;
}

