using System;
using System.Collections.Generic;

// 네이티브 오디오 엔진. 테스트는 가짜 구현을 넣는다. 모든 호출은 메인 스레드에서만 일어난다.
public interface IAudioBackend
{
    // 뱅크를 네이티브 메모리에 올리고 0 보다 큰 핸들을 돌려준다. 실패하면 예외를 던진다.
    int Load(string bankName);

    // 핸들을 해제한다. 같은 핸들을 두 번 해제하거나 해제한 핸들을 쓰면 네이티브 쪽이 죽는다.
    void Unload(int handle);
}

// 여러 화면이 같은 오디오 뱅크를 나눠 쓰도록 참조 수를 세는 캐시.
public sealed class AudioBankCache
{
    private sealed class Entry
    {
        public int Handle;
        public int Count;   // 살아 있는 임대 수. 0 이 되면 Unload 하고 사전에서 지운다.
    }

    private readonly IAudioBackend _backend;
    private readonly Dictionary<string, Entry> _entries = new Dictionary<string, Entry>(StringComparer.Ordinal);
    private bool _shutDown;

    public AudioBankCache(IAudioBackend backend)
    {
        _backend = backend ?? throw new ArgumentNullException(nameof(backend));
    }

    internal bool IsShutDown => _shutDown;

    // bankName 을 빌린다. 처음 빌리면 Load 해 참조 수 1, 이미 올라와 있으면 Load 없이 참조 수 +1.
    // 부를 때마다 새 임대(BankLease)를 돌려준다. 임대 하나 = 참조 하나.
    // bankName 이 null 이나 빈 문자열이면 ArgumentException, Shutdown 뒤에는 ObjectDisposedException.
    // Load 가 예외를 던지면 그대로 전파하고 아무것도 기록하지 않는다.
    public BankLease Acquire(string bankName)
    {
        if (string.IsNullOrEmpty(bankName)) throw new ArgumentException("뱅크 이름이 비어 있습니다.", nameof(bankName));
        if (_shutDown) throw new ObjectDisposedException(nameof(AudioBankCache));

        if (!_entries.TryGetValue(bankName, out Entry entry))
        {
            // Load 를 먼저 한다: 여기서 예외가 나면 사전에 아무것도 남지 않는다.
            int handle = _backend.Load(bankName);
            entry = new Entry { Handle = handle };
            _entries.Add(bankName, entry);
        }
        entry.Count++;
        return new BankLease(this, bankName, entry.Handle);
    }

    // 지금 살아 있는 임대 수. 올라와 있지 않으면 0.
    public int RefCount(string bankName)
    {
        return bankName != null && _entries.TryGetValue(bankName, out Entry entry) ? entry.Count : 0;
    }

    // BankLease.Dispose 의 첫 호출에서만 불린다.
    internal void Release(string bankName)
    {
        if (_shutDown) return;                       // 이미 Shutdown 이 모두 Unload 했다
        Entry entry = _entries[bankName];            // 살아 있던 임대가 있으므로 반드시 있다
        entry.Count--;
        if (entry.Count == 0)
        {
            _entries.Remove(bankName);               // 다음 Acquire 는 새로 Load 한다
            _backend.Unload(entry.Handle);           // 마지막 반납 시점에 즉시, 정확히 한 번
        }
    }

    // 게임 종료 때 부른다. 아직 올라와 있는 뱅크를 하나씩 정확히 한 번 Unload 하고,
    // 그 뱅크 이름들(= 반납되지 않은 임대가 남아 있던 뱅크, 누수)을 순서 비교(Ordinal)로 정렬해 돌려준다.
    // 두 번째 호출부터는 아무것도 하지 않고 빈 배열을 돌려준다.
    public string[] Shutdown()
    {
        if (_shutDown) return Array.Empty<string>();
        _shutDown = true;

        var leaked = new string[_entries.Count];
        _entries.Keys.CopyTo(leaked, 0);
        Array.Sort(leaked, StringComparer.Ordinal);
        foreach (string name in leaked) _backend.Unload(_entries[name].Handle);
        _entries.Clear();
        return leaked;
    }
}

// 뱅크 하나에 대한 참조 하나.
public sealed class BankLease : IDisposable
{
    private readonly AudioBankCache _owner;
    private readonly int _handle;
    private bool _disposed;

    internal BankLease(AudioBankCache owner, string bankName, int handle)
    {
        _owner = owner;
        BankName = bankName;
        _handle = handle;
    }

    public string BankName { get; }

    // 뱅크의 네이티브 핸들. 이 임대를 Dispose 했거나 캐시가 Shutdown 되었으면 ObjectDisposedException.
    public int Handle
    {
        get
        {
            if (_disposed || _owner.IsShutDown) throw new ObjectDisposedException(nameof(BankLease), BankName + " 임대는 이미 반납되었습니다.");
            return _handle;
        }
    }

    // 참조를 반납한다. 첫 호출만 참조 수를 1 줄이고, 그 결과 0 이 되면 이 호출 안에서 즉시 Unload 한다.
    // 두 번째 호출부터와 Shutdown 뒤의 호출은 아무것도 하지 않는다(예외도 던지지 않는다).
    public void Dispose()
    {
        if (_disposed) return;      // IDisposable 규약: 두 번째 호출부터는 무시한다
        _disposed = true;
        _owner.Release(BankName);
    }
}

