{{USER_CODE}}

public static class __Judge
{
    // 가짜 네이티브 엔진: 호출을 기록하고, 이중 해제·모르는 핸들 해제를 오류로 모은다.
    sealed class FakeBackend : IAudioBackend
    {
        public readonly System.Collections.Generic.List<string> Loads = new System.Collections.Generic.List<string>();
        public readonly System.Collections.Generic.List<int> Unloads = new System.Collections.Generic.List<int>();
        public readonly System.Collections.Generic.Dictionary<int, string> Live = new System.Collections.Generic.Dictionary<int, string>();
        public readonly System.Collections.Generic.List<string> Errors = new System.Collections.Generic.List<string>();
        public string FailNext;
        int _next = 100;
        public int Load(string bankName)
        {
            Loads.Add(bankName);
            if (bankName == FailNext) { FailNext = null; throw new System.IO.IOException("bank file missing: " + bankName); }
            int h = ++_next;
            Live[h] = bankName;
            return h;
        }
        public void Unload(int handle)
        {
            Unloads.Add(handle);
            if (!Live.Remove(handle)) Errors.Add("이미 해제했거나 모르는 핸들 " + handle + " 을 Unload 함(네이티브 크래시)");
        }
    }

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Throws<T>(System.Action a, string what) where T : System.Exception
    {
        try { a(); }
        catch (T) { return null; }
        catch (System.Exception e) { return what + ": " + typeof(T).Name + " 기대 / 결과 " + e.GetType().Name; }
        return what + ": " + typeof(T).Name + " 기대 / 결과 예외 없음";
    }

    static string Count(AudioBankCache c, string bank, int want, string when)
    {
        int got = c.RefCount(bank);
        return got == want ? null : when + ": RefCount(\"" + bank + "\") 기대 " + want + " / 결과 " + got;
    }

    static string Calls(FakeBackend b, int loads, int unloads, string when)
    {
        if (b.Errors.Count > 0) return when + ": " + b.Errors[0];
        if (b.Loads.Count != loads) return when + ": Load 호출 횟수 기대 " + loads + " / 결과 " + b.Loads.Count;
        if (b.Unloads.Count != unloads) return when + ": Unload 호출 횟수 기대 " + unloads + " / 결과 " + b.Unloads.Count;
        return null;
    }

    public static void Main()
    {
        Run("acquire-loads-once", () =>
        {
            var b = new FakeBackend(); var c = new AudioBankCache(b);
            var l1 = c.Acquire("bgm_battle"); var l2 = c.Acquire("bgm_battle"); var l3 = c.Acquire("bgm_battle");
            string e = Calls(b, 1, 0, "같은 뱅크를 세 번 Acquire") ?? Count(c, "bgm_battle", 3, "세 번 Acquire 뒤");
            if (e != null) return e;
            if (ReferenceEquals(l1, l2) || ReferenceEquals(l2, l3)) return "Acquire 가 같은 임대 객체를 다시 돌려줌(임대 하나 = 참조 하나여야 함)";
            if (l1.Handle != l2.Handle || l2.Handle != l3.Handle) return "같은 뱅크의 임대들이 서로 다른 Handle 을 가짐";
            if (l1.BankName != "bgm_battle") return "BankName 기대 bgm_battle / 결과 " + l1.BankName;
            var s = c.Acquire("sfx_ui");
            e = Calls(b, 2, 0, "다른 뱅크 Acquire") ?? Count(c, "sfx_ui", 1, "sfx_ui Acquire 뒤") ?? Count(c, "never_loaded", 0, "올라온 적 없는 뱅크");
            if (e != null) return e;
            return s.Handle != l1.Handle ? null : "다른 뱅크가 같은 Handle 을 가짐";
        });

        Run("last-release-unloads-immediately", () =>
        {
            var b = new FakeBackend(); var c = new AudioBankCache(b);
            var l1 = c.Acquire("bgm"); var l2 = c.Acquire("bgm"); var l3 = c.Acquire("bgm");
            int h = l1.Handle;
            l1.Dispose();
            string e = Calls(b, 1, 0, "임대 3개 중 1개 반납") ?? Count(c, "bgm", 2, "1개 반납 뒤");
            if (e != null) return e;
            l3.Dispose();
            e = Calls(b, 1, 0, "임대 3개 중 2개 반납") ?? Count(c, "bgm", 1, "2개 반납 뒤");
            if (e != null) return e;
            l2.Dispose();
            e = Calls(b, 1, 1, "마지막 임대를 반납한 직후(Dispose 안에서 즉시 Unload 되어야 함)") ?? Count(c, "bgm", 0, "모두 반납 뒤");
            if (e != null) return e;
            if (b.Unloads[0] != h) return "Unload 한 핸들 기대 " + h + " / 결과 " + b.Unloads[0];
            var again = c.Acquire("bgm");
            e = Calls(b, 2, 1, "모두 반납한 뒤 다시 Acquire(새로 Load 해야 함)") ?? Count(c, "bgm", 1, "다시 Acquire 뒤");
            if (e != null) return e;
            return again.Handle != h ? null : "해제한 핸들 " + h + " 을 다시 돌려줌";
        });

        Run("double-dispose-is-ignored", () =>
        {
            var b = new FakeBackend(); var c = new AudioBankCache(b);
            var menu = c.Acquire("voice"); var battle = c.Acquire("voice");
            menu.Dispose(); menu.Dispose(); menu.Dispose();
            string e = Calls(b, 1, 0, "한 임대를 세 번 Dispose(다른 임대는 살아 있음)") ?? Count(c, "voice", 1, "한 임대를 세 번 Dispose 한 뒤");
            if (e != null) return e;
            if (battle.Handle <= 100) return "살아 있는 임대의 Handle 이 이상함: " + battle.Handle;
            battle.Dispose();
            e = Calls(b, 1, 1, "남은 임대 반납");
            if (e != null) return e;
            menu.Dispose(); battle.Dispose();
            return Calls(b, 1, 1, "Unload 된 뒤 두 임대를 다시 Dispose") ?? Count(c, "voice", 0, "모두 반납 뒤");
        });

        Run("use-after-release-throws", () =>
        {
            var b = new FakeBackend(); var c = new AudioBankCache(b);
            var a = c.Acquire("ambient"); var keep = c.Acquire("ambient");
            int h = keep.Handle;
            a.Dispose();
            string e = Throws<System.ObjectDisposedException>(() => { int x = a.Handle; }, "반납한 임대의 Handle 읽기");
            if (e != null) return e;
            if (keep.Handle != h) return "다른 임대를 반납한 뒤 살아 있는 임대의 Handle 이 바뀜";
            keep.Dispose();
            return Throws<System.ObjectDisposedException>(() => { int x = keep.Handle; }, "마지막 임대를 반납한 뒤 그 Handle 읽기") ?? Calls(b, 1, 1, "모두 반납 뒤");
        });

        Run("bad-name-and-load-failure", () =>
        {
            var b = new FakeBackend(); var c = new AudioBankCache(b);
            string e = Throws<System.ArgumentException>(() => c.Acquire(null), "Acquire(null)") ?? Throws<System.ArgumentException>(() => c.Acquire(""), "Acquire(\"\")")
                ?? Calls(b, 0, 0, "잘못된 이름으로 Acquire(Load 하면 안 됨)");
            if (e != null) return e;
            b.FailNext = "boss_theme";
            e = Throws<System.IO.IOException>(() => c.Acquire("boss_theme"), "Load 가 IOException 을 던질 때 Acquire");
            if (e != null) return e;
            e = Count(c, "boss_theme", 0, "Load 가 실패한 뒤");
            if (e != null) return e;
            var ok = c.Acquire("boss_theme");
            e = Calls(b, 2, 0, "실패 뒤 다시 Acquire(다시 Load 해야 함)") ?? Count(c, "boss_theme", 1, "다시 Acquire 뒤");
            if (e != null) return e;
            ok.Dispose();
            return Calls(b, 2, 1, "반납 뒤") ?? Count(c, "boss_theme", 0, "반납 뒤");
        });

        Run("shutdown-unloads-and-reports-leaks", () =>
        {
            var b = new FakeBackend(); var c = new AudioBankCache(b);
            var bgm1 = c.Acquire("bgm_battle"); var bgm2 = c.Acquire("bgm_battle");
            var voice = c.Acquire("Voice_Boss"); var hit = c.Acquire("sfx_hit"); var ui = c.Acquire("ui_click");
            ui.Dispose();
            string[] leaks = c.Shutdown();
            string got = leaks == null ? "(null)" : string.Join(",", leaks);
            if (got != "Voice_Boss,bgm_battle,sfx_hit") return "Shutdown 이 돌려준 누수 목록 기대 [Voice_Boss,bgm_battle,sfx_hit](Ordinal 정렬) / 결과 [" + got + "]";
            string e = Calls(b, 4, 4, "Shutdown 직후");
            if (e != null) return e;
            if (b.Live.Count != 0) return "Shutdown 뒤에도 해제되지 않은 핸들이 " + b.Live.Count + "개 남음";
            string[] second = c.Shutdown();
            if (second == null || second.Length != 0) return "두 번째 Shutdown 은 빈 배열이어야 함";
            e = Calls(b, 4, 4, "두 번째 Shutdown 뒤") ?? Throws<System.ObjectDisposedException>(() => c.Acquire("bgm_battle"), "Shutdown 뒤 Acquire")
                ?? Throws<System.ObjectDisposedException>(() => { int x = bgm1.Handle; }, "Shutdown 뒤 남은 임대의 Handle 읽기");
            if (e != null) return e;
            bgm1.Dispose(); bgm2.Dispose(); voice.Dispose(); hit.Dispose();
            return Calls(b, 4, 4, "Shutdown 뒤 남은 임대들을 Dispose(Unload 가 다시 불리면 안 됨)") ?? Count(c, "bgm_battle", 0, "Shutdown 뒤");
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(7405);
            string[] banks = { "a", "b", "c", "d" };
            for (int run = 0; run < 40; run++)
            {
                var b = new FakeBackend(); var c = new AudioBankCache(b);
                var live = new System.Collections.Generic.List<BankLease>();
                var dead = new System.Collections.Generic.List<BankLease>();
                var model = new System.Collections.Generic.Dictionary<string, int>();
                int loads = 0, unloads = 0;
                for (int op = 0; op < 400; op++)
                {
                    int r = rng.Next(10);
                    string what;
                    if (r < 5 || live.Count == 0)
                    {
                        string name = banks[rng.Next(banks.Length)];
                        model.TryGetValue(name, out int n);
                        if (n == 0) loads++;
                        model[name] = n + 1;
                        live.Add(c.Acquire(name));
                        what = "Acquire(" + name + ")";
                    }
                    else if (r < 9 || dead.Count == 0)
                    {
                        int k = rng.Next(live.Count);
                        var lease = live[k]; live.RemoveAt(k); dead.Add(lease);
                        string name = lease.BankName;
                        model[name]--;
                        if (model[name] == 0) unloads++;
                        lease.Dispose();
                        what = "Dispose(" + name + ")";
                    }
                    else
                    {
                        var lease = dead[rng.Next(dead.Count)];
                        lease.Dispose();
                        what = "이미 반납한 " + lease.BankName + " 임대를 다시 Dispose";
                    }
                    string e = Calls(b, loads, unloads, "무작위 " + run + "회차 " + op + "번째 " + what);
                    if (e != null) return e;
                    foreach (string name in banks)
                    {
                        model.TryGetValue(name, out int want);
                        e = Count(c, name, want, "무작위 " + run + "회차 " + op + "번째 " + what + " 뒤");
                        if (e != null) return e;
                    }
                }
                var expected = new System.Collections.Generic.List<string>();
                foreach (string name in banks) if (model.TryGetValue(name, out int n) && n > 0) expected.Add(name);
                string got = string.Join(",", c.Shutdown());
                if (got != string.Join(",", expected)) return "무작위 " + run + "회차 Shutdown 누수 목록 기대 [" + string.Join(",", expected) + "] / 결과 [" + got + "]";
                if (b.Errors.Count > 0 || b.Live.Count != 0) return "무작위 " + run + "회차 Shutdown 뒤 오류 또는 남은 핸들: " + (b.Errors.Count > 0 ? b.Errors[0] : b.Live.Count + "개");
            }
            return null;
        });
    }
}
